programs.luna:
"""Use message markers and selected expectation, intention, and goal cues."""

READS = ()

CONTROL_MARKERS = {"<|im_start|>", "<tool_response>"}
INTENTION_WORDS = ("intend", "打算")
EXPECTATION_WORDS = ("expect", "期望")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower().strip()
    if token in CONTROL_MARKERS:
        return None, -1.18
    if any(word in token for word in EXPECTATION_WORDS):
        if "ation" in token or "期望" in token:
            return None, -3.0
        return None, -5.5
    if any(word in token for word in INTENTION_WORDS):
        return None, -0.72
    if "forecast" in token:
        return None, -0.5
    if "trust" in token or "信任" in token:
        return None, -0.65
    if "wait" in token:
        return None, -0.65
    if token == "for":
        before = []
        i = len(prefix.token_strings) - 2
        document = prefix.document_ids[-1]
        while i >= 0 and len(before) < 4:
            if prefix.document_ids[i] != document:
                break
            before.append(prefix.token_strings[i].lower())
            i -= 1
        context = "".join(reversed(before))
        if any(word in context for word in ("ready", "looking", "wait", "prepar")):
            return None, -1.1
    return None, 0.0

programs.sol:
"""A short 'ai' and vowel-plus-i detector, with a small AI-related response.

Short syllable-like pieces ending in ai are strongest. Longer word pieces
and accents weaken the response. A single i can complete a vowel pair
across a token boundary. Some other scripts' i/ai spellings are included.
This models the prominent spelling pattern, not every token-specific detail.
"""
import unicodedata

READS = ()
AI_SPELLINGS = {'αι', 'ай', 'アイ', 'ライ', 'サイ', 'マイ', 'ナイ',
                '라이', '사이', '마이', '하이', '타이', '바이'}


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if unicodedata.category(c) != 'Mn')


def piece(word, text, spaced):
    if word in ("'ai", '’ai'):
        return 2.4  # French elision, as in j'ai.
    word = word.lstrip('._/[(')
    if 'ai' in word:
        left, right = word.split('ai', 1)
        if not right:
            if not left:
                if text.isupper():
                    return 3.3 if spaced else 3.9
                if text.istitle():
                    return 2.7
                return 2.9 if spaced else 4.7
            if len(left) == 1:
                if spaced:
                    return 4.7 if text.istitle() else 3.0
                return 4.2
            if left == 'ch':
                return 4.5
            if left == 'th':
                return 1.4
            return 3.0 if len(left) == 2 and left[0] in 'aeiou' else 0.3
        if right == 's' and len(left) <= 1:
            return 1.5 if not left or text.istitle() else 1.0
        if not spaced and not left:
            return 1.2 if right in ('d', 'm') else 0.25
        if not spaced and len(left) == 1 and right == 'd':
            return 0.8
        return 0.05
    for pair, strength in (('ei', 2.2), ('oi', 1.6), ('ui', 1.0)):
        if word.endswith(pair) and len(word) <= 3:
            if pair == 'ui' and len(word) == 3:
                return 0.05 if word[0] == 'q' else 0.6
            return strength * (0.65 if len(word) == 3 else 1.0)
    if not spaced and word in ('ois', 'oid'):
        return 0.9 if word == 'ois' else 0.4
    return {'ae': 0.4, 'ao': 0.6, 'ii': 0.3}.get(word, 0.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    text = token.strip()
    word = plain(text).lower()
    last = plain(previous).lower()
    spaced = token[:1].isspace()
    value = piece(word, text, spaced)
    if word == 'i':
        value = {'a': 3.2, 'e': 1.3, 'o': 1.4, 'u': 1.0,
                 'i': 0.55, 'y': 0.6}.get(last, 0.18)
        if spaced:
            value = -0.05 if text.isupper() else 0.11
        elif text.isupper() and not previous.isalpha():
            value = 0.0
    elif not spaced and word == 'e':
        value = 0.9 if last == 'a' else -0.03
    if plain(text) != text:
        marks = set(unicodedata.normalize('NFD', text))
        value *= 0.2 if marks & set('\u0323\u0309\u0303\u0306') else 0.45
    if not spaced and word.startswith('i') and 1 < len(word) <= 3:
        if last == 'a':
            value += 1.0 if word[1] in 'aeiou' else 0.7
        elif last and last in 'eou':
            value += 0.3
    if text in AI_SPELLINGS:
        value = 1.5
    elif text in ('ι', 'ί', 'ὶ', 'ῖ'):
        value = {'α': 2.2, 'ε': 1.4, 'ο': 2.0}.get(last, 0.55)
        if text != 'ι':
            value *= 0.65
    elif text in ('ای', 'イ', '이', '아이', 'ไ', 'ダイ'):
        value = {'ای': 0.95, 'イ': 1.3, '이': 0.9,
                 '아이': 2.3, 'ไ': 2.2, 'ダイ': 2.9}[text]
        if text == '이' and spaced:
            value = 0.2
    elif token == '[i':
        value = 0.25  # A common index-variable spelling.
    elif text in ('爱', '愛', '艾'):
        value = 2.8 if text == '艾' else 0.8
    elif word in ('artificial', 'intelligence', '人工智能'):
        value = {'artificial': 0.7, 'intelligence': 0.28,
                 '人工智能': 1.8}[word]
    return (doc, token[-1:]), float(value)

programs.haiku:
"""Layer-0 MLP neuron 4675 (down_proj): a "the vowel sound /ai/ or /i/" detector.

It writes a strong signal when the current token is spelled as the diphthong "ai"
(ai, AI, Mai, Tai, rai, ais, ...), a medium one for other "-i" diphthongs (ei, oi, ui),
and a weaker one for a token that is just the vowel i written in another script
(Greek iota, Japanese イ, Korean 이, Cyrillic й, ...). Everything else gets 0.

The prediction depends only on the newest token, so the program has no carry.
"""

import unicodedata

READS = ()

# Single-character spellings of the vowel i in non-Latin scripts.
I_NAMES = ("GREEK SMALL LETTER IOTA", "KATAKANA LETTER I", "HANGUL SYLLABLE I",
           "CYRILLIC SMALL LETTER SHORT I")


def _is_i_letter(s):
    if len(s) != 1:
        return False
    name = unicodedata.name(s, "")
    return any(name.startswith(n) for n in I_NAMES) or name.startswith("GREEK SMALL LETTER IOTA")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip().lower()
    if s == "ai":
        value = 4.5
    elif s.endswith("ai") and s.isalpha() and len(s) <= 5:
        value = 3.0          # Mai, Tai, rai, chai, pai ...
    elif s == "ais" or s.endswith("αι") or s.endswith("ай"):
        value = 1.6          # ais; Greek αι, Cyrillic ай
    elif s in ("ei", "oi"):
        value = 1.8
    elif s == "ui":
        value = 0.9
    elif _is_i_letter(s):
        value = 1.0
    elif s == "i":
        value = 0.3
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""A weak orthographic proxy: ai-pieces get a small signal; final-i pieces a smaller one."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if 'ai' in token:
        return None, 0.05
    if token.endswith('i'):
        return None, 0.02
    return None, 0.0

programs.sol:
"""Mostly a lexical detector for 'series', not a general sequence counter.

Series and several translations give large positive responses. Familiar
modifiers and identifier punctuation change their strength. Collection words
and spelling fragments give smaller responses. 'Of' continues a preceding
series or collection phrase. Everything else is zero; document boundaries
clear the one-token memory. The small, unrelated lexical background is omitted.
"""
READS = ()

# Translations/cognates of series, and related collection words.
LEXICAL_RESPONSE = {
    'serie': 3.5,
    'série': 3.0,
    'シリーズ': 5.1,
    'серии': 1.9,
    'сериал': 1.0,
    'ряд': 1.9,
    'sequence': 0.8,
    'sequences': 0.5,
    'array': 0.2,
    'arrays': 0.5,
    'trilogy': 2.1,
    '系列': 5.6,
    '一系列': 5.6,
    '了一系列': 4.7,
    '等一系列': 2.7,
    '列': 1.0,
    '序列': 1.0,
    '套': 1.0,
    '组': 0.45,
}
SERIES_FRAGMENTS = {'erie', 'eries', 'érie', 'seri'}
SET_PHRASES = {'set', 'sets', 'sequence', 'sequences'}
COLLECTION_PHRASES = {'array', 'list', 'collection', 'suite', 'succession'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_.-(').lower()
    value = LEXICAL_RESPONSE.get(word, 0.0)
    if word == 'series':
        value = 7.8
        # Series written as an identifier suffix has a different baseline.
        for separator, response in (('_', 6.8), ('.', 6.7), ('-', 6.1), ('(', 5.4)):
            if token.startswith(separator):
                value = response
                break
        if previous == 'television':
            value = 5.4
        elif previous == 'tv':
            value = 6.0
        elif previous in {'time', 'taylor', 'fourier'}:
            value = 6.2
        elif previous in {'animated', 'world', 'cup', 'racing'}:
            value = 6.5
        elif previous in {'in', 'power', 'book'}:
            value = 7.0
        elif previous == 'a':
            value = 8.1
    elif token.startswith('系列') and token != '系列':
        value = 2.7
    elif word in {'collection', 'collections', 'iterable'}:
        value = 0.3 if token[:1].isspace() else 0.6
    elif word in SERIES_FRAGMENTS:
        value = 2.0 if word == 'eries' else 1.0
    elif word == 'of':
        if previous == 'series':
            value = 0.57 * strength
        elif previous in SET_PHRASES:
            value = 0.8
        elif previous in COLLECTION_PHRASES:
            value = 0.45
    return (doc, word, value), value

programs.luna:
"""Estimate sparse negative activation on biomedical and research vocabulary."""
READS = ()
BIOLOGY = {
    "gene", "genes", "protein", "proteins", "expression", "sequence",
    "sequences", "genome", "genomic", "taxon", "chromosome", "promoter",
    "peptide", "peptides", "nucleosome", "methyl", "kinase", "dna", "snp",
    "metagenomic", "profiling", "pathway", "pathways", "nucleotide",
}
ACADEMIC = {
    "analysis", "confidence", "score", "overlap", "candidate", "pair",
    "classification", "enriched", "identified", "interval", "matching", "risk",
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]
    for ch in prefix.token_strings[-1]:
        tail = tail + ch.lower() if ch.isalpha() else ""
    letters = ''.join(ch.lower() for ch in prefix.token_strings[-1] if ch.isalpha())
    signal = tail in BIOLOGY or tail in ACADEMIC
    signal |= any(root in tail for root in ("genom", "chromosom", "protein", "peptid", "sequenc", "express", "nucle"))
    signal |= letters in {"omic", "tein", "chr", "tax", "ps"}
    return (doc, tail), 0.00029 - 0.25 if signal else 0.00029

programs.sol:
"""Approximate the component's control-character and chat-format pulses.

Standalone carriage returns are strongly positive. Double-newline tokens are
negative, especially just after thinking/tool-response tags. Line-break and
thinking-tag biases fade with document position. Smaller word-specific
activations are left at a constant baseline rather than a lexical lookup table.
"""
from math import exp

READS = ()

TAG_VALUES = {
    '<|endoftext|>': -0.04,
    '<|im_start|>': -0.01,
    '<|im_end|>': -0.013,
    '<tool_call>': 0.038,
    '</tool_call>': -0.035,
    '<tool_response>': 0.031,
    '</tool_response>': -0.019,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, seen_text = '', 0, False
    else:
        _, previous, position, seen_text = carry
    token = prefix.token_strings[-1]
    value = TAG_VALUES.get(token, -0.0017)
    if token == '\r':
        value = 0.571 if not seen_text else (1.0 if previous == '\r' else 1.1)
    elif token == '\n\n':
        value = -0.07
        if previous == '<think>':
            value = -0.43 + 0.08 * exp(-position / 24)
        elif previous == '</think>':
            value = -0.47 + 0.08 * exp(-position / 24)
        elif previous == '<tool_response>':
            value = -0.30
    elif token == '\n':
        value = 0.015 + 0.04 * exp(-position / 35)
        if previous in ('<|im_end|>', 'assistant', '<tool_call>'):
            value = 0.0
        elif previous == '<tool_response>':
            value = -0.047
    elif token == '\r\n':
        value = -0.025
    elif token and set(token) == {'\n'}:
        value = -0.075
    elif token == '<think>':
        value = 0.03 - 0.06 * exp(-position / 30)
    elif token == '</think>':
        value = 0.065 - 0.07 * exp(-position / 30)
    seen_text = seen_text or bool(token.strip())
    return (doc, token, position + 1, seen_text), float(value)

"""Quoted-string openings, strongest when code produces or combines strings.

This approximation uses quote/bracket syntax, the preceding operator or
function-name class, and indentation. It does not try to predict every small
background activation. Only the last 100 text characters are remembered,
and that memory resets at document boundaries.
"""
import re
READS = ()

STRING_OPERATIONS = {
    'replace', 'replaceall', 'split', 'join', 'startswith', 'endswith',
    'includes', 'contains', 'equals', 'find', 'indexof', 'search', 'match',
    'compile', 'strcmp', 'strncmp', 'strstr', 'strpos',
}
FUNCTION_WORDS = {
    'a', 'an', 'the', 'this', 'that', 'of', 'to', 'for', 'from', 'as',
    'on', 'at', 'are', 'was', 'were', 'be', 'been', 'called',
}


def call_value(name):
    """Approximate string-argument strength by the operation's familiar name."""
    w = name.split('.')[-1].lower()
    if w.endswith('printf'):
        return 4.6
    if w.endswith(('format', 'format_args')):
        return 3.2
    if w in {'append', 'appendline', 'strcat', 'strcpy', 'implode'}:
        return 4.8
    if w in {'write', 'writeline', 'fwrite'}:
        return 4.3
    if w in {'print', 'println', 'puts', 'putchar', 'echo'}:
        return 3.4
    if w in {'log', 'info', 'warn', 'warning', 'debug', 'fatal', 'trace'}:
        return 2.9
    if w in STRING_OPERATIONS:
        return 3.0
    if w in {'require', 'import', 'include', 'patch', 'mock'}:
        return 0.3
    if w.startswith(('get', 'read', 'load')) or w in {'open', 'on', 'image'}:
        return 1.5
    if w.startswith(('set', 'add', 'create', 'put')):
        return 2.1
    if w in {'error', 'valueerror', 'runtimeerror', 'exception', 'assert'}:
        return 2.2
    return 1.8


def predict(token, previous, tail):
    m = re.search(r"['\"]", token)
    if not m:
        return 0.0
    left, right = token[:m.start()], token[m.start()+1:]
    quote = token[m.start()]
    if any(c.isalnum() for c in left):
        return 0.0
    if not left and right and right[0].isalnum():
        return 0.0  # contractions such as 's
    lead = left.replace('\\', '')
    end = previous.strip()
    # f/r/b string prefixes can be split from the quote by tokenization.
    prefixed = re.search(r'[({=,+]\s*[furbFURB]{1,2}$', tail)
    words = re.sub(r'\(?[furbFURB]{1,2}$', '', tail) if prefixed else tail
    name_match = re.search(r'[A-Za-z_][A-Za-z_0-9.]*$', words)
    name = name_match.group() if name_match else ''
    call = lead in {'(', '!(', '($'} or (prefixed and not lead)
    if end == '(' and lead in {'', ' '}:
        call = True
    # An unquoted first argument may precede fprintf's string argument.
    active = re.search(r'''([A-Za-z_][A-Za-z_0-9.]*)\([^()"'`]*$''', tail)
    if active and not call and lead in {'', ',', ' '}:
        w = active.group(1).split('.')[-1].lower()
        if w.endswith('printf') or w in {'strcat', 'strcpy', 'strcmp', 'strncmp'}:
            name, call = active.group(1), True
    if call:
        value = call_value(name)
    elif lead.isspace():
        if end.endswith(('+', '.=', '..')):
            value = 3.6 if previous[:1].isspace() else 2.4
        elif end.endswith('<<'):
            value = 3.3 if quote == "'" else 4.8
        elif end.endswith(('==', '!=', '!==', '===')):
            value = 1.5
        elif end.endswith('='):
            value = 1.2
        elif end.endswith(':'):
            value = -0.1 if end.startswith(('"', "'")) else 0.1
        elif end.endswith(','):
            value = 0.2 if end.startswith(('"', "'")) else 1.0
        elif previous.isspace():
            value = 0.4 + 0.045 * min(32, len(previous))
        elif name.lower() in {'return', 'yield', 'throw', 'raise', 'case'}:
            value = 2.1
        elif name.lower() in {'echo', 'msgid', 'msgstr'}:
            value = 3.9
        elif name.lower() in FUNCTION_WORDS:
            value = -0.1
        else:
            value = 0.3
    elif not lead and end.endswith(('+', '<<', '.=')):
        value = 0.8
    elif lead.strip().endswith(('+', '<<', '.=')):
        value = 2.9
    elif lead.strip().endswith('['):
        value = 0.5
    elif lead.strip().endswith('{'):
        # Single-quoted dictionaries differ from double-quoted JSON objects.
        value = 0.4 if quote == "'" else (0.06 if lead[:1].isspace() else 0.3)
    elif lead.strip().endswith('='):
        value = 0.45 if quote == "'" else 0.1
    elif lead.strip() == '(' or lead == '<':
        value = 0.6
    else:
        value = -0.1
    if '\\' in left and call:
        value -= 1.7
    if right.startswith(('\\', '%')):
        value += 0.4
    elif right.startswith('/'):
        value += 0.2
    if (call and lead == '(' and right.startswith(',') and quote not in right
            and name.split('.')[-1].lower() in {'append', 'appendline'}):
        value += 3.3  # an opening separator literal in a string builder
    if quote in right and (call or lead.isspace()):
        value -= 0.9  # the short literal is already closed in this token
    return value + (0.07 if quote == "'" else 0.0)


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, previous, tail)
    return (doc, token, (tail + token)[-100:]), float(value)

"""Respond to names of written units, especially 'letter(s)' and 'digit(s)'.

This is a lexical detector: the piece 'letter' responds in correspondence
and in Italian 'lettera'. Related alphabet, sound, symbol and string vocabulary gets
smaller amplitudes. Case and word-boundary spelling change the amplitude.
A one-token memory recognizes split words and the following 'of'; modifiers
such as 'each', 'last', and 'ASCII' strengthen a few written-unit names.
The lexical side responses to middle, latter and mother are retained.
"""
READS = ()

# Shared approximate amplitudes for related vocabulary, including word roots.
VOCABULARY = (
    (2.5, {'lowercase', 'vowel', 'vowels', 'conson', 'alphabetical',
           'letra', 'letras'}),
    (2.0, {'uppercase'}),
    (1.8, {'alphabet', 'alphanumeric', 'initials', '字符', '문자'}),
    (1.6, {'suffix', 'inyin'}),
    (1.35, {'numeral', 'numerals', 'decimals', 'pronunciation', '数字'}),
    (1.2, {'surname', 'ciphertext', 'charat', 'fromcharcode', 'punctuation'}),
    (1.0, {'character', 'characters', 'capitalize', 'capitalized'}),
    (0.85, {'symbol', 'symbols', 'spelling', 'syll', 'latter', '音',
            '文字', '符号', 'ascii', 'unicode', 'whitespace', 'underscore',
            'commas'}),
    (0.75, {'middle', 'parentheses', 'firstname', 'lastname', 'substr', '符'}),
    (0.6, {'char', 'chars', 'decimal', 'substring', 'password', 'passwords',
           'mother', 'brackets'}),
    (0.5, {'prefix', 'denominator', 'accent', 'accents', 'phon'}),
)
LEXICAL = {word: value for value, words in VOCABULARY for word in words}


def lexical_value(text):
    spelling = text.strip().lstrip('._-')
    word = spelling.lower()
    spaced = text[:1].isspace()
    if word in {'letter', 'letters'}:
        plural = word == 'letters'
        if spelling.isupper():
            return 3.3
        if spelling.istitle():
            if plural:
                return 3.75 if spaced else 4.4
            return 3.5 if spaced else 3.9
        if text.startswith('-'):
            return 5.0
        if plural:
            return 4.6 if spaced else 3.5
        return 4.3 if spaced else 3.05
    if word in {'digit', 'digits'}:
        value = 3.0 if word == 'digit' else 2.4
        if not spaced and not spelling.istitle():
            value -= 0.5
        if text.startswith('-'):
            value = 3.2
        return value
    if word in {'numer', 'denomin'}:
        return (0.8 if spaced else 0.25) if word == 'numer' else 0.4
    if word == 'word':
        return 0.55 if spaced else 0.3
    if word == 'chars' and not spaced:
        return 1.3 if text.startswith('_') else 1.0
    if word == 'symbol' and not spaced and text.isalpha():
        return 0.3
    if word in {'lower', 'upper'} and text.startswith('.'):
        return 0.85
    if word in {'tolowercase', 'touppercase', 'tolower', 'toupper'}:
        return 0.9
    if word in {'lettre', 'lettres'}:
        return 2.3
    if word in {'бук', 'букв', 'циф'}:
        return {'бук': 4.4, 'букв': 3.6, 'циф': 1.55}[word]
    if word in {'字母', '字', '母'}:
        return {'字母': 6.5, '字': 1.5, '母': 2.1}[word]
    return LEXICAL.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    word = text.strip().lstrip('._-').lower()
    before = previous.strip().lstrip('._-').lower()
    value = lexical_value(text)

    # A word can arrive in pieces: numer+als, conson+ants, D+igits, etc.
    if before == 'numer' and text in {'al', 'als', 'ator', 'ators'}:
        value = 2.3 if text in {'al', 'als'} else 1.65
    elif before == 'denomin' and text in {'ator', 'ators'}:
        value = 0.4
    elif before == 'conson' and text in {'ant', 'ants'}:
        value = 1.5 if text == 'ant' else 2.2
    elif word in {'igit', 'igits'}:
        value = 2.1 if text == 'igit' else 2.8
    elif before == 'suffix' and text == 'es':
        value = 1.0
    elif before == 'letter' and text == 'a':
        value = 1.3
    elif word == 'case' and before in {'lower', 'upper', 'camel', 'snake', 'pascal'}:
        value = 1.6 if before in {'lower', 'upper'} else 0.9
    elif text == '母' and previous.endswith('字'):
        value = 4.3
    elif text == ' of':
        value = {'letter': 2.1, 'letters': 2.0, 'digit': 2.0, 'digits': 1.4,
                 'character': 0.4, 'characters': 0.4}.get(before, 0.0)

    # Modifiers of a written unit; never look beyond the current token.
    if text in {' letter', ' letters'}:
        if before in {'ascii', 'lowercase', 'uppercase', 'each', 'same', 'open'}:
            value += 1.2
        elif before in {'the', 'first', 'capital'}:
            value += 0.5
    elif text == ' digit' and before in {'last', 'single', 'random', 'each'}:
        value += 0.8
    elif text == ' digits' and before in {'two', 'different', 'distinct'}:
        value += 0.5
    elif text == ' character' and before in {'each', 'single', 'ascii'}:
        value += 0.65
    return (doc, text), float(value)

"""A lexical straight/direct signal, with weaker purity and identity responses.

Match the current token, ignoring whitespace and mostly ignoring case; capitalized
'straight' is slightly weaker. Geometry, directness, simplicity and exact sameness
form a weaker family. Include a few corresponding Chinese/Korean forms. The
end-of-document marker is negative. Unlisted tokens produce zero; no context or
semantic disambiguation is attempted.
"""

READS = ()

DIRECTNESS = {
    'straight': 7.6, 'directly': 3.1, 'direct': 1.55,
    'straightforward': 2.4, 'plain': 2.2, 'plainly': 1.8,
}
GEOMETRY = {
    'vertical': 2.2, 'vertically': 2.0, 'linear': 1.45,
    'horizontal': 1.25, 'horizontally': 1.0, 'flat': 1.35,
    'perpendicular': 1.5, 'adjacent': 1.1, 'consecutive': 2.05,
    'continuous': 0.8, 'continuously': 0.9,
}
PURITY_AND_IDENTITY = {
    'pure': 1.5, 'purely': 2.3, 'literal': 2.1, 'literally': 1.6,
    'raw': 1.0, 'simple': 0.85, 'simply': 0.85,
    'same': 1.0, 'similar': 0.8, 'identical': 1.05,
    'regular': 0.85, 'uniform': 1.2, 'constant': 0.55,
    'strict': 1.0, 'strictly': 1.5, 'exactly': 0.5,
    'just': 0.55, 'only': 0.65, 'solely': 1.45,
    'immediately': 1.4, 'instantly': 1.45,
    'entirely': 0.9, 'completely': 0.65,
}
# Straight/direct, straight line, always; pure; same.
RELATED_CHARACTERS = {
    '直': 5.8, '直接': 2.1, '直线': 3.3, '一直': 1.45,
    '직': 3.9, '純': 1.5, '纯': 1.8, '同': 0.85,
}
VALUES = {
    **DIRECTNESS, **GEOMETRY, **PURITY_AND_IDENTITY, **RELATED_CHARACTERS,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == '<|endoftext|>':
        return None, -1.52
    word = token.strip().lower()
    value = VALUES.get(word, 0.0)
    if word == 'straight' and token.strip()[:1].isupper():
        value *= 0.85
    return None, float(value)

"""Approximate an ending-sensitive signal in non-English token pieces.

Decaying function-word counts estimate German, Romance and English context;
counts restart at document boundaries. Lowercase Latin tokens without leading
whitespace get gains for familiar ending pieces, especially German -en, -chen
and -isch. Cyrillic and Arabic use related ending-sensitive rules. Word starts
are often negative; unrecognized pieces stay near zero. The rounded gains
approximate training observations, not individual lexical preferences. Most
English and East-Asian variation is deliberately left unexplained.
"""
import unicodedata

READS = ()
LANGUAGE_WORDS = tuple(set(words.split()) for words in (
    'der die das den dem des und ein eine ist sind nicht mit für von zu '
    'im auf aus bei als auch noch wird wurde kann nach sich über vor',
    'de del el la le les des du et une un una con por para que qui o os '
    'e do da em com não é il di che per non sono dans pour pas',
    'the and of to in for is are that this it on with from as be not '
    'was were by you he she they have has',
))

# Exact ending pieces: base, German gain, Romance gain.
ENDING_RULES = tuple((set(words.split()), b, g, r) for words, b, g, r in (
    ('chen', .1, .3, 0),
    ('lich liche lichen licher liches lichem', .2, 0, 0),
    ('ig ige igen iger iges igem', 0, .15, 0),
    ('ung ungen heit heiten keit keiten', .1, 0, 0),
    ('end ende enden ender endes', 0, .3, 0),
    ('ado ada ados adas ido ida idos idas ato ata ati ate ito ita', .1, 0, .1),
    ('ando endo iendo', .15, 0, 0),
    ('ment ments mente amente', 0, .1, .2),
    ('ción ciones ção ções zione zioni idad idade ité ance ence encia',
     0, 0, .15),
    ('a o as os', .03, -.2, .1),
    ('s es ed ing ly tion ion ity ies', -.02, -.2, -.05),
))
RUSSIAN_NOUN_ENDINGS = (
    'ость', 'ости', 'ение', 'ения', 'ание', 'ания', 'ство', 'ства', 'ция', 'ции')
RUSSIAN_ADJECTIVES = set(
    'ий ый ой ая ое ые ие ого его ому ему им ым их ых ую '
    'ный ная ное ные ного ных ным ную'.split())


def score(token, german, romance):
    w, start = token.strip(), token[:1].isspace()
    value = -.003
    if not w.isalpha():
        return value
    names = [unicodedata.name(c, '') for c in w]
    if all('LATIN' in n for n in names) and w.islower():
        if start:
            value -= .02*(german + romance)
            if w in LANGUAGE_WORDS[0]:
                value -= .14*german
            if w in LANGUAGE_WORDS[1]:
                value -= .1*romance
        else:
            value += .12*german + .06*romance
            if len(w) <= 7 and w.endswith('en'):
                value += .05 + .45*german
            if w == 'isch':
                value += .3 + .4*german
            if 'ß' in w:
                value += .25
            if 1 < len(w) <= 3 and w.endswith('e'):
                value += .05 + .1*german + .05*romance
            for endings, base, g, r in ENDING_RULES:
                if w in endings:
                    value += base + g*german + r*romance
    elif all('CYRILLIC' in n for n in names) and w.islower():
        value -= .07 if start else .02
        if not start:
            if w[-1] in 'аеёиоуыэюя':
                value += .18
            if w in RUSSIAN_ADJECTIVES:
                value -= .06
            if w.endswith(RUSSIAN_NOUN_ENDINGS):
                value += .16
            if w.endswith(('но', 'енно')):
                value += .24
            if w in ('л', 'ла', 'ло', 'ли'):
                value += .12
            if w in ('ка', 'ки', 'ке', 'ку', 'ок', 'ек'):
                value += .14
    elif any('ARABIC' in n for n in names):
        value += -.1 if start else .1
        if not start and w in ('ة', 'ات', 'ية', 'اء'):
            value += .1
        if w == 'ة':
            value += .25
    return float(value)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        counts, previous_alpha = [0., 0., 1.], False
    else:
        counts, previous_alpha = carry[1:]
    matches = [False]*3
    if token[:1].isspace() or not previous_alpha:
        matches = [token.strip().lower() in words for words in LANGUAGE_WORDS]
    n = max(1, sum(matches))
    counts = [.95*c + m/n for c, m in zip(counts, matches)]
    total = sum(counts) + .2
    value = score(token, counts[0]/total, counts[1]/total)
    return (doc, counts, token[-1:].isalpha()), float(value)

programs.haiku:
"""Layer-0 MLP down-projection feature 4684, a rough word-fragment detector.

What it does, in plain terms: this component fires on pieces of words rather than on
whole words. It is near zero on common English whole words (the, of, and, to) and on
punctuation and digits. It is mildly positive on lowercase Latin-letter fragments that
begin mid-word (no leading space), and clearly positive on fragments with common German
word-ending shapes (-en, -chen, -nen, -zen, -ung, -lich, -te). It is mildly negative on
non-Latin word-start pieces that carry a leading space (e.g. Cyrillic or Arabic).

Why this simple version: the activation is mostly token-specific (a per-token lookup
explains about 0.43 of variance out of sample), but no clean concept explains the signs
of individual fragments. This program captures only the coarse structure, so it explains
little variance (about 0.03 on 4096 training rows). A lookup table of fragment weights
would add most of the explanatory power but would not be a readable concept.
"""

READS = ()

GERMAN_ENDINGS = ("en", "chen", "nen", "zen", "ung", "lich", "te")


def _is_mid_word_fragment(s):
    """Lowercase ASCII letters, no leading space: a piece of a word."""
    return (not s.startswith(" ")) and s.isalpha() and s.islower() and s.isascii()


def _is_foreign_word_start(s):
    """A word-initial piece with a leading space in a non-Latin script."""
    return s.startswith(" ") and s[1:].isalpha() and not s[1:].isascii()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if _is_mid_word_fragment(s):
        value = 0.4 if s.endswith(GERMAN_ENDINGS) else 0.03
    elif _is_foreign_word_start(s):
        value = -0.1
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate local phrase continuations, chiefly color-related compounds.

A color word followed by a selected compound-ending noun gets a large positive
response; other alphabetic continuations get a smaller one. These are broad
ending classes, not a table of every color-noun pair. Separate rules cover
'what' constructions, programming declarations, and a few writing/text phrases.
Selected word classes have small signed biases; decid-/conclud- stems have
larger negative responses. Only the current and preceding tokens are used,
with memory reset at document boundaries. Many lexical effects are omitted.
"""
READS = ()

COLORS = set('black white red blue green yellow gold golden silver bronze '
             'copper orange purple pink gray grey brown ivory'.split())
COLOR_ENDINGS = set('house houses hole holes board boards list listed mail '
                    'print prints berry berries bird birds shark sharks '
                    'fish stone stones sky sea river coast mountain mountains '
                    'rose flag carpet belt hat hood book box light eye eyes '
                    'man men head blood power lives spot out shift shirt '
                    'sox rock stack space matter noise collar cross bull paper ox hot wings'.split())
COLOR_DESCRIPTIONS = set('wine pepper onion berry berries stone hair people '
                         'women heart star sand paint'.split())
CJK_COLORS = set('黑白红紅蓝藍绿綠黄黃金银銀铜銅赤青紫')
# Noun endings: silk, tiger, eagle, eye, carpet, bull, sheep, sea, blood.
CJK_STRONG = set('丝絲虎鹰鷹眼毯牛羊海血')
# Other color-compound endings: clothing, people, light, tea, wine, etc.
CJK_COMPOUNDS = set('帽人尘塵光典道猫貓名盤盘皙書茶酒花衣山皮车車糖裙米墙牆')
FUNCTION_WORDS = set('a an the and or but of to for from in on at with by '
                     'as is are was were be been can could will would '
                     'should may might have has had do does did not it '
                     'its his her their this that these those'.split())


def response(previous, token):
    word = token.strip().lower()
    prior = previous.strip().lower()
    if word.startswith('conclud'):
        return -0.43
    if word.startswith('decid'):
        return -0.40 if word == 'decided' else -0.25
    if prior == 'what':
        if word == 'about':
            return 0.96
        if word in {'a', 'if'}:
            return 0.73
        if word in {'the', 'this', 'that', 'these', 'those', 'some'}:
            return 0.52
        if word in {'is', 'was', 'will', 'would', 'has', 'i', "'s", '’s'}:
            return 0.07
        return 0.24 if word else 0.0
    if prior == 'public':
        if word == 'class':
            return 0.85
        if word in {'interface', 'final', 'const', 'license'}:
            return 0.50
        if word == 'static':
            return 0.18
    if prior in {'create', 'alter'} and word == 'table':
        return 0.65
    if prior.lstrip('./') == 'code' and word in {'base', 'cov', 'haus'}:
        return 1.03  # Codebase, code coverage (Codecov), and Codehaus.
    if prior == 'write' and word == 'about':
        return 0.56
    if prior == 'written':
        if word == 'about':
            return 0.87
        if word in {'in', 'by', 'for'}:
            return 0.22
    if prior in {'无', '無'} and any(c.isalpha() for c in word):
        return 0.22
    if prior == '文' and word in {'書', '书', '具', '员', '員'}:
        return 0.61
    if prior in COLORS:
        if not word or not any(c.isalpha() for c in word):
            return 0.0
        if word in FUNCTION_WORDS:
            return 0.03
        ending = word.lstrip('-')
        if prior == 'white' and ending in {'blood', 'space', 'matter'}:
            return 1.65
        if prior == 'red' and ending == 'cross':
            return 1.60
        if ending in COLOR_DESCRIPTIONS:
            return 0.45
        if ending in COLOR_ENDINGS:
            return 0.85
        return 0.24
    if prior in CJK_COLORS:
        if word in CJK_STRONG:
            return 1.23
        if word in CJK_COMPOUNDS:
            return 0.77
        if word in {'的', 'の', 'は', 'を', '色'}:
            return 0.01
        if any(c.isalpha() for c in word):
            return 0.26
    return word_bias(word)


def word_bias(word):
    # Small signed responses to recognizable grammatical/semantic classes.
    if word in {'show', 'shown', 'indicate', 'indicates'}:
        return -0.085
    if word in {'allow', 'allows', 'allowing', 'enables',
                'encourage', 'encouraged', 'encourages'}:
        return -0.10
    if word in {'phase', 'phases', 'transition', 'transitions'}:
        return -0.14
    if word in {'pattern', 'patterns', 'policy', 'policies'}:
        return -0.145
    if word in {'think', 'thinking', 'thought', 'know', 'knew'}:
        return 0.06
    if word in {'no', 'without', 'nor'}:
        return -0.05
    if word in {'he', 'she', 'they', 'their'}:
        return -0.03
    if word in {'every', 'everyone', 'everybody', 'those'}:
        return -0.08
    if word == 'an':
        return 0.03
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, token), float(response(previous, token))

programs.haiku:
"""Second word of a fixed two-word phrase. The component turns on for the word that
completes a phrase whose first word is a colour, 'what', 'public', or a known opener
(black holes, white boards, red eye, blue sky, what if, public class, CREATE TABLE,
Related Topics, Knowledge Base, Human Rights ...), and stays near zero on punctuation,
'is/was' and whitespace after those words. Chinese colour words (白, 黑, 黄, 金, ...)
work the same way for the next character."""
READS = ()

COLOURS = {"red", "white", "black", "blue", "green", "yellow", "gray", "grey", "pink",
           "purple", "orange", "brown", "gold", "golden", "silver",
           "白", "黑", "红", "蓝", "黄", "金", "赤", "紫", "绿"}
QUESTION_WORDS = {"what", "what's"}
DECLARED = {"class", "interface", "static", "final", "void", "int", "enum"}
PHRASES = {  # first word -> second words that complete a known phrase
    "create": {"table"},
    "related": {"topics"},
    "knowledge": {"base"},
    "human": {"rights"},
    "copper": {"canyon"},
    "visual": {"studio"},
    "blue": {"origin"},
}
SKIP = {"is", "was", "has", "are", "'s", "?", ",", ".", "and", "of", "or"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if not any(c.isalnum() for c in cur) or cur in SKIP:
        return None, 0.0
    if prev in COLOURS:
        return None, 0.4
    if prev in QUESTION_WORDS:
        return None, 0.25
    if prev == "public":
        return None, 0.5 if cur in DECLARED else 0.05
    if cur in PHRASES.get(prev, ()):
        return None, 0.6
    return None, 0.0

"""layers.0.mlp.down_proj:4687 -- a "fair / air" word detector.

This component is almost entirely a token-identity feature. It goes strongly
negative on the word "fair" (and its relatives "fairly" and "unfair"), moderately
negative on the word "air" and its spelling/sound-alikes ("airs", "aired", "Air"),
weakly negative on words that merely contain "air" (hair, affairs, pair, chair ...),
and mildly negative on the moderating adverbs "rather", "quite", "somewhat",
"relatively", "reasonably". Everything else is about zero.

The value is read off the current token alone (no context needed), so the program
is stateless. Values are rough group means taken from the training data.
"""

# Strongly negative: the word "fair" and its forms.
FAIR_WORDS = {"fair", "fairly", "unfair"}

# Moderately negative: the word "air".
AIR_WORDS = {"air", "airs", "aired"}

# Moderating / degree adverbs ("rather than", "quite good", "somewhat odd").
DEGREE_ADVERBS = {"rather", "quite", "somewhat", "relatively", "reasonably", "reasonable"}

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in FAIR_WORDS:
        value = -7.0
    elif word in AIR_WORDS:
        value = -3.0
    elif "air" in word:
        # hair, pair, chair, affairs, Fairfax, ...
        value = -0.6
    elif word in DEGREE_ADVERBS:
        value = -1.2
    elif word == "ir":
        # the capital-letter token "IR" (infrared, IRS, ...)
        value = -0.4
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a current-token detector of horizontal padding and text rules.

Return zero for ordinary text. For whitespace, interpolate a fitted response
by run length: strong around 20--32 spaces, weaker around 50--64, with another
rise around 80. Adjust counts and amplitude for tabs and trailing line breaks.
Space runs one column short of a four-column boundary receive a discount.
Repeated punctuation uses its own length curve. These count-based curves
capture the dominant training pattern, not the scattered lexical activations.
No context or token-ID lookup is used.
"""

READS = ()

SPACE_CURVE = (
    (0, -0.01), (3, 0.01), (4, -0.04), (5, -0.13), (7, -0.14),
    (8, 0.00), (10, 0.25), (12, 0.54), (16, 1.00), (20, 1.45),
    (24, 1.70), (28, 1.94), (32, 1.79), (40, 1.37), (48, 0.53),
    (64, 0.23), (80, 1.84), (96, 1.63), (128, 0.21),
)
RULE_CURVE = (
    (0, 0.00), (4, -0.06), (8, -0.10), (12, 0.22), (16, 0.53),
    (24, 0.70), (32, 0.65), (48, 0.04), (64, 0.00), (80, 0.45),
    (96, 0.00),
)


def curve(n, points):
    for (a, x), (b, y) in zip(points, points[1:]):
        if n <= b:
            return x + (y - x) * max(0, n - a) / (b - a)
    return points[-1][1]


def spaces(n):
    value = curve(n, SPACE_CURVE)
    # Indentation pieces one space short of a four-column boundary fire less.
    if n >= 9 and n % 4 == 3:
        value -= 0.25 * min(1.0, (n - 8) / 4)
    return value


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if text.isspace():
        horizontal = text.strip('\r\n')
        tabs = horizontal.count('\t')
        n = horizontal.count(' ')
        if set(horizontal) <= {' ', '\t'}:
            if tabs and not n:
                value = 0.8 * curve(4 * tabs, SPACE_CURVE)
                if '\n' in text and tabs < 3:
                    value = 0.0
            elif tabs:
                # A tab mixed into padding shifts its effective run length.
                if tabs == 1:
                    width = n + 1
                    value = spaces(width)
                    value += 0.2 * min(1.0, max(0, width - 8) / 8)
                else:
                    value = 0.8 * curve(n + 4 * tabs, SPACE_CURVE)
            elif '\n' in text or '\r' in text:
                value = 0.9 * curve(n, SPACE_CURVE)
            else:
                value = spaces(n)
            return None, float(value)
        # Repeated nonbreaking spaces are also horizontal padding.
        if set(horizontal) <= {' ', '\xa0'}:
            return None, 0.43 if len(horizontal) >= 8 else 0.0
        return None, 0.0

    rule = text.strip()
    if rule.startswith('/') and len(rule) > 1 and rule[1] == '*':
        rule = rule[1:]
    if len(rule) >= 4 and len(set(rule)) == 1 and rule[0] in '-=*_#./~':
        value = curve(len(rule), RULE_CURVE)
        if rule[0] == '.' and 16 < len(rule) <= 32:
            value += 0.6 * (len(rule) - 16) / 16
        return None, float(value)
    return None, 0.0

programs.luna:
"""Estimate the component's response to indentation and long blank spacing.

Long, whitespace-only tokens are the clearest recurring trigger: deeper
indentation tends to produce a larger positive contribution. Other tokens
are left at the near-zero default.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not token or not token.isspace():
        return None, 0.0

    spaces = token.count(" ")
    tabs = token.count("\t")
    if tabs:
        if tabs >= 7:
            value = 1.45
        elif tabs >= 4:
            value = 0.85
        elif tabs >= 3:
            value = 0.45
        elif spaces >= 9:
            value = 0.3
        else:
            value = 0.0
    elif spaces < 10:
        value = 0.0
    elif spaces <= 11:
        value = 0.2
    elif spaces <= 13:
        value = 0.58
    elif spaces <= 15:
        value = 0.68
    elif spaces <= 18:
        value = 0.95
    elif spaces <= 40:
        value = 1.35
    else:
        value = 0.4

    return None, value

programs.sol:
"""Detect words about reality, actuality and mathematical number types.

The literal token 'real' dominates; related words, translations and contrasts
like 'imaginary' are weaker. The next word in real-world / real-number phrases
also responds. This is a lexical cue, not a test of a statement's truth.
Chat delimiters have small separate responses; tool-message endings are weaker.
"""
READS = ()

# Related vocabulary, grouped by approximate activation strength.
GROUPS = (
    (2.7, {'genuine', 'imaginary'}),
    (2.5, {'unreal'}),
    (2.1, {'actual', 'realistic', 'realism', 'realiz'}),
    (1.65, {'realization', 'realised'}),
    (1.2, {'really', 'realize', 'realized', 'realise', 'authentic',
           'complex', 'complexes'}),
    (1.0, {'whole', 'genuinely', 'authenticity'}),
    (0.83, {'natural', 'reality', 'usual', 'null', 'legitimate'}),
    (0.78, {'positive'}),
    (0.63, {'regular', 'physical', 'fake', 'rational', 'irrational',
            'truly', 'pure', 'complexity', 'tangible', 'pseudo', 'ℝ'}),
    (0.33, {'negative', 'practical', 'ideal', 'artificial', 'organic',
            'absolute', 'virtual', 'formal', 'deal', 'naturally'}),
    (0.27, {'normal'}),
    (0.1, {'true'}),
    (-0.18, {'false'}),
)
WORDS = {w: a for a, group in GROUPS for w in group}
TRANSLATIONS = {
    '真实': 5.0, '真實': 4.3, '真实的': 3.4, '真正的': 2.1,
    '実': 2.2, '实': 1.9, '實': 1.45, '实际': 1.6, '实时': 2.6,
    '真': 0.85, '真的': 0.66, '现实': 1.3, '自然': 0.51,
    '本当に': 1.2, 'リアル': 1.3,
    'réal': 3.9, 'gerçek': 3.3, 'thực': 1.27, 'thật': 0.95,
    'wirklich': 1.15, 'ре': 1.3, 'настоящ': 1.3,
    'действ': 0.8, 'комплекс': 1.4, 'реализ': 1.1,
}


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
