programs.sol:
"""Approximate a strong two-period cue and weaker repetition cues.

Training activations distinguish a pair of periods from a three-dot ellipsis.
This program recognizes those pairs, including parent-directory notation,
and adjusts their strength for quotes, line endings and nearby text. A pair
at a line start or after `from` receives a boost; preceding dot runs weaken it.
Smaller responses cover repeated sentence marks, nonbreaking spaces and
thinking delimiters. Everything else is zero: diffuse word-specific responses
are deliberately omitted rather than stored in a vocabulary lookup table.
"""
import math

READS = ()


def response(token, line_start, previous):
    core = token.strip(' \t\r\n')
    if '../' in core:
        depth = core.count('../')
        value = 2.5 - 0.2 * token.startswith(' ')
        value += 1.2 * ("'" in core) + 0.5 * ('"' in core)
        value -= 1.7 * ('=' in core) + 0.9 * ('(' in core)
        value += 0.5 * core.startswith('/')
        return value / depth ** 0.7
    if '..' in core and core.count('.') == 2 and '…' not in core:
        before, after = core.split('..')
        newlines = token.count('\n')
        value = 5.85 + 0.8 * (token.startswith(' ') and newlines < 2)
        value -= 0.8 * ('"' in before)
        value += 0.3 * ("'" in before) + 0.6 * (')' in before)
        value -= 1.3 * bool(set(after) & set("'\"\\<"))
        value -= 1.7 * bool(newlines) + 0.9 * max(0, newlines - 1)
        value += 0.8 * line_start
        value += 2.2 * (previous.strip() == 'from')
        value -= 1.5 * previous.rstrip().endswith('..')
        return max(0.0, value)
    if len(core) >= 2 and len(set(core)) == 1:
        mark, count = core[0], len(core)
        if mark == '.':
            if count == 3:
                return -0.05
            return 0.3 if '\n' in token else 0.8
        if mark in '!?':
            value = (1.2 if mark == '!' else 0.9) if count == 2 else 0.55
            return value * (0.7 if '\n' in token else 1.0)
        if mark in ',;':
            return (0.9 if mark == ',' else 0.7) * 2 / count
        if mark == '。':
            return 2.27 / (count - 1) ** 0.8
        if mark == '・':
            return 1.65 if count == 2 else 0.4
        if mark in '！？':
            return 0.7 if count == 2 else 0.4
        if mark == '^':
            return 0.65
        if mark == '~':
            return 0.33 * math.sqrt(2 / count)
        if mark == '·':
            return 0.32
        if mark == '\xa0':
            return 0.66 if count == 2 else 0.8 / count
    if core.startswith('…') and set(core[1:]) == {'.'}:
        return 0.93
    if token == '</think>':
        return 0.93
    if token == '<think>':
        return 0.20
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line_start = '', True
    else:
        _, previous, line_start = carry
    token = prefix.token_strings[-1]
    value = response(token, line_start, previous)
    if '\n' in token:
        line_start = not token.rsplit('\n', 1)[-1].strip()
    elif token.strip():
        line_start = False
    return (doc, token, line_start), float(value)

