"""Estimate this sparse response from visible punctuation and layout cues.

A two-dot token is the strongest cue. Smaller rules cover repeated marks,
nonbreaking spaces, a relative path, and the <think> boundary markers. Other
tokens receive zero. The estimates are conservatively scaled down.
"""

READS = ()
SCALE = 0.75


def _step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip(" \t\r\n")

    if bare == "..":
        if token.startswith(" ") and "\n" not in token:
            return None, 7.3
        if "\n" in token:
            return None, 4.6
        return None, 5.6

    if token == "</think>":
        return None, 0.95
    if token == "<think>":
        return None, 0.22
    if "../" in token:
        return None, 2.1

    if "\u00a0" in token:
        count = token.count("\u00a0")
        if count == 2:
            return None, 0.6
        if count <= 4:
            return None, 0.27
        return None, 0.16

    if bare == "。。":
        return None, 2.5
    if bare in ("!!", "！！"):
        return None, 1.0
    if bare in ("???", "??"):
        return None, 0.7
    if bare in ("....", "…", "……"):
        return None, 0.78

    # Modest responses to other doubled symbols, such as tildes or carets.
    if len(bare) == 2 and bare[0] == bare[1]:
        if not bare[0].isalnum() and not bare[0].isspace():
            return None, 0.45

    return None, 0.0


def step(carry, prefix, upstream):
    carry, value = _step(carry, prefix, upstream)
    return carry, SCALE * value

