# Surface forms of the English copula, and third-person singular equivalents:
# French est, German ist, Portuguese é, Italian è, and Spanish es/está.
OTHER_COPULAS = {
    ' was': 0.02, ' are': 0.00, ' were': -0.19, ' am': -0.11,
    ' be': -0.03, ' been': -0.05,
    ' est': 0.30, ' ist': 0.18, ' é': 0.21, ' è': 0.25,
    ' es': 0.13, ' está': 0.26,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    previous_word = previous.strip().lower()
    value = OTHER_COPULAS.get(token, -0.001)

    if token == ' is':
        if not previous:
            value = 0.93
        elif previous_word == 'what':
            value = -0.25
        elif previous_word in {'it', 'this'}:
            value = 0.02
        elif previous_word in {'that', 'there', 'here'}:
            value = 0.15
        elif previous_word in {'which', 'who', 'how', 'why'}:
            value = 0.26
        elif previous_word in {'he', 'she'}:
            value = 0.38
        elif len(previous_word) <= 1 or not any(c.isalpha() for c in previous):
            value = 0.82
        elif not previous.startswith(' '):
            value = 0.74
        elif previous.strip().istitle():
            value = 0.70
        elif len(previous_word) <= 3:
            value = 0.73
        else:
            value = 0.61
    elif token.strip() == 'Is':
        value = 0.46
    elif token == ' IS':
        value = 0.32
    elif token != 'is' and token.lstrip(' \t./_-(#') == 'is':
        value = 0.42
    elif token.strip() == 'is':
        value = 0.44 if not previous or not previous[-1].isalpha() else 0.05
    return (document, token), value

