"""The verb 'to be' in the present tense, as the word 'is' (or its foreign equivalents
est, ist, è, é, está), fires after a noun or other non-pronoun subject: 'The cat is',
'the answer is', 'x (2) is'. It is silent after a subject pronoun or 'what/this/there'
('It is', 'This is', 'What is'), and a bit lower after 'which/who/he' ('which is').
The weaker past and plural forms ('was', 'are') give a small positive value after a noun
and a small negative value after a pronoun; 'were' is slightly negative throughout."""
READS = ()

# How strongly each form of 'to be' fires when the subject is a noun.
IS_FORMS = {" is": 1.0, " Is": 0.8, " est": 0.45, " ist": 0.3, " è": 0.35, " é": 0.3, " está": 0.4}
WEAK_FORMS = {" was": 0.1, " are": 0.1}

# Words before the verb that switch it off, and words that only half switch it on.
NO_SUBJECT = {"It", "it", "This", "this", "That", "that", "What", "what", "There", "there"}
WEAK_SUBJECT = {"which", "Which", "who", "Who", "he", "He", "she", "She", "they", "They",
                "we", "We", "I", "you", "You"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    pronounish = before in NO_SUBJECT or before in WEAK_SUBJECT
    if token in IS_FORMS:
        if before in NO_SUBJECT:
            subject = 0.0
        elif before in WEAK_SUBJECT:
            subject = 0.35
        else:
            subject = 0.68
        return None, subject * IS_FORMS[token]
    if token in WEAK_FORMS:
        return None, -0.1 if pronounish else WEAK_FORMS[token]
    if token == " were":
        return None, -0.17
    return None, 0.0

programs.sol:
"""Detect opening parentheses after content, rather than mere grouping.

Names, numbers and ordinary words followed by a spaced '(' get the strongest
response. Grammatical connectors and operators weaken it. Parentheses joined
to an identifier also respond, with weaker responses for quoted arguments,
nesting and empty pairs. Square brackets get a smaller response. Otherwise
predict zero. Remember only a short text tail, resetting at each document.
Amplitudes summarize training observations; small background activity is omitted.
"""
import re

READS = ()
CONNECTORS = set('''
    the an is are am be was were being been of for from to by at in on with as
    into between than and or but if while that because whether when where
    which although so then else will would should could can may might must
    do does did have has had about above below under over through without
    within since until after before via either neither both each every any
    all some such these those this other also not only even though thus hence
    therefore however otherwise perhaps maybe why how what who whom whose
    you it they them we us he she here there like his her its their our my your
'''.split())
GROUPING_WORDS = set('''
    give gives equals equal becomes contains contain requires implies define
    consider find involving constitute let use take using provide return
    throw yield except
'''.split())
MATH_WORDS = set('''
    equation equations expression expressions formula point points pair pairs
    coordinate coordinates values catch func left right
'''.split())
MATH_FUNCTIONS = set('''
    sin cos tan sqrt ln log exp min max range len print printf println left right
'''.split())


def word_at_end(text):
    match = re.search(r'\w+$', text.rstrip())
    return match.group() if match else ''


def context_strength(text):
    text = text.rstrip()
    if not text:
        return 0.15
    char, word = text[-1], word_at_end(text)
    if char.isdigit():
        return 2.3
    if char.isalpha():
        lower = word.lower()
        if word.isupper():
            return 1.8 if len(word) == 1 else 2.3
        if lower in CONNECTORS:
            return 0.1
        if word == 'a':
            return 0.95
        if lower in GROUPING_WORDS:
            return 0.55
        if lower in MATH_WORDS:
            return 1.3
        return 1.8 if len(word) == 1 else 2.25 if word[0].isupper() else 2.05
    if char in '=:':
        return -0.15
    if char in '([':
        return 0.2
    if char in '+-<>;,?.':
        return 0.45
    return 1.75 if char in ')]}' else 2.0 if char in '\"\'`”’%' else 0.8


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    old, previous = ('', '') if start else carry[1:]
    old = old.replace('\\n', ' ').replace('\\t', ' ')
    value = 0.0
    if '(' in token:
        before, after = token.split('(', 1)
        if ')' in token:
            if token.count('(') > token.count(')'):
                value = 1.2
            elif token.rfind('(') > token.rfind(')'):
                value = 0.56
        elif not after:
            if before.isspace():
                value = context_strength(old)
            elif before:
                value = (0.12 if before.endswith('\\') else
                         0.0 if before.endswith('{') else 1.0)
            else:
                word = word_at_end(old)
                if word in MATH_FUNCTIONS:
                    value = 1.0
                else:
                    value = 1.5 if len(word) > 1 else 1.15 if word else 0.65
                if word in {'if', 'for', 'while'}:
                    value = 0.3
                if start:
                    value = -0.78
            if previous and not previous.strip():
                value = 0.7 if '\n' in previous else 0.95
        elif after.isalpha():
            value = 1.4 if len(after) == 1 else 1.7 + 0.05 * min(len(after), 12)
        elif after.startswith('('):
            value = -0.1 if before.isspace() else 0.53
        elif after[0] in '{[':
            value = 0.2
        elif after.isspace():
            value = 0.75 if not before else 0.2
        else:
            value = (1.45 if after.startswith('\\') else
                     1.6 if after[0] in '$&@#' else 0.85)
        if start and not before and after and ')' not in token:
            value -= 1.05
    elif '（' in token and '）' not in token:
        prior = old.rstrip()[-1:]
        value = (-0.5 if start or prior in {':', '：'} else
                 1.6 if prior.isalnum() else 0.6)
    elif '[' in token:
        after = token.split('[', 1)[1]
        value = 0.05 if ']' in token else 0.7 if after.isalpha() else 0.5
    return (doc, (old + token)[-80:], token), float(value)

"""Introducing punctuation, with a smaller expressive-punctuation response.

A terminal colon is strongest. Equals signs, question/exclamation marks,
ellipses and double dashes are weaker. Spaces, newlines, or extra symbols in
that same token often suppress the response; URL and comparison syntax do not
behave like plain punctuation. Other text is predicted as zero.

For the main punctuation classes, use the preceding token's word shape,
common field labels, document position, and the number of alphabetic runs
since the last period, question/exclamation mark, semicolon, colon or newline.
These distinguish longer phrases from numbers, short labels and code.
"""
import math

READS = ()
FIELD_LABELS = {
    "name", "type", "title", "version", "date", "author",
    "subject", "posts", "joined", "re", "key", "id",
}
BLOCK_ENDINGS = {"else", "try", "finally", "except", "True", "False", "None"}
BOUNDARIES = frozenset("\r\n.:!?;。！？：")


def token_response(s):
    """Base response and the familiar punctuation class to adjust for context."""
    t = s.strip()
    space = s[:1].isspace()
    newline = '\n' in s or '\r' in s
    if not t or any(c.isalnum() for c in t):
        return 0.0, None
    if ':' in t or '：' in t:
        if t.count(':') > 1 or '/' in t:
            return -0.04, None
        if t.endswith(':='):
            return 0.63, None
        if t.endswith(':\\'):
            return 0.49, None
        if not t.endswith((':', '：')):
            return 0.12, None
        if newline:
            if ')' in t and s.count('\n') == 1:
                return 0.08, None
            return 0.40, 'line_colon'
        if t.endswith('：'):
            return 0.98, None
        return (0.78, 'spaced_colon') if space else (1.40, 'colon')
    if '=' in t:
        if t.count('=') > 1:
            return -0.09, None
        if any(c in t for c in '<>!'):
            return 0.02, None
        if not t.endswith('='):
            return (-0.15 if any(c in t for c in '\"\'{[') else 0.0), None
        if newline:
            return 0.22, None
        if any(c in t for c in '+-*/%&^'):
            return 0.25, None
        if any(c in t for c in ')]}'):
            return 0.64, None
        return 0.55, 'equals'
    if any(c in t for c in '?!？！'):
        if newline:
            return (0.02 if '?' in t or '？' in t else 0.14), None
        if not t.endswith(tuple('?!？！')) or '<' in t:
            return 0.10, None
        if any(c in t for c in '([{'):
            return 0.08, None
        if space or any(c in t for c in '？！'):
            return 0.29, None
        if t.count('?') + t.count('!') > 1:
            return 0.33, None
        return 0.65, 'sentence'
    if '…' in t or (len(t) >= 2 and set(t) == {'.'}):
        if newline:
            return 0.10, None
        if space or t == '..' or len(t) > 4:
            return 0.33, None
        return 0.64, 'sentence'
    if '--' in t:
        return (0.16 if newline or '>' in t or t.count('-') > 2 else 0.56), None
    return 0.0, None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, words, inside_word = 0, '', 0, False
    else:
        _, position, previous, words, inside_word = carry
        position += 1
    s = prefix.token_strings[-1]
    value, kind = token_response(s)
    if kind:
        word = previous.strip()
        number = word.isdigit()
        letter = len(word) == 1 and word.isalpha()
        spaced_word = previous[:1].isspace() and word.isalpha()
        capitals = word.isalpha() and word.isupper()
        punctuation = bool(previous) and not any(c.isalnum() for c in previous)
        identifier = any(c in word for c in '_.') and any(c.isalnum() for c in word)
        label = word.lower() in FIELD_LABELS
        early = math.exp(-position / 64.0)
        phrase = math.log1p(words)
        if kind == 'colon':
            value += -0.23 + 0.63 * early + 0.24 * phrase
            value -= 0.47 * number + 0.28 * letter + 0.15 * capitals
            value += 0.06 * spaced_word
            value -= 0.27 * punctuation + 0.29 * identifier + 0.49 * label
        elif kind == 'spaced_colon':
            value += 0.05 + 0.27 * early + 0.12 * phrase
            value -= 0.45 * number + 0.34 * letter
            value -= 0.30 * punctuation + 0.35 * identifier + 0.32 * label
        elif kind == 'line_colon':
            value += -0.14 + 0.19 * early + 0.08 * phrase - 0.11 * number
            if word in BLOCK_ENDINGS:
                value -= 0.25
        elif kind == 'sentence':
            value += -0.15 + 0.21 * early + 0.05 * phrase
            value -= 0.16 * number + 0.09 * letter + 0.08 * capitals
            value += 0.08 * spaced_word
            value -= 0.19 * punctuation + 0.10 * identifier
        elif kind == 'equals':
            value += -0.08 + 0.15 * early + 0.03 * phrase - 0.08 * number
            value += 0.02 * letter + 0.04 * s[:1].isspace()
    for char in s:
        if char in BOUNDARIES:
            words, inside_word = 0, False
        elif char.isalpha():
            if not inside_word:
                words += 1
            inside_word = True
        else:
            inside_word = False
    return (doc, position, s, words, inside_word), float(value)

