"""A small vocabulary cue for action and behavior language.

The component is usually quiet, but negative on words naming an action,
activity, operation, interaction, or behavior. The action word itself can
produce a much larger response than the neighboring words.
"""

READS = ()

STRONG_ACTION_WORDS = {"action", "-action"}
PLURAL_ACTIONS = {"actions"}
RELATED_WORDS = {
    "operation", "operations", "activity", "activities", "actively",
    "interaction", "interactions", "behavior", "behaviour", "verb",
    "行动", "行動", "行为", "行為", "操作", "作",
    "azione", "فعل",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in STRONG_ACTION_WORDS:
        return None, -7.0
    if word in PLURAL_ACTIONS:
        return None, -5.1
    if word in RELATED_WORDS or word.endswith(("behaviour", "behavior")):
        return None, -1.0
    return None, 0.0

programs.haiku:
"""Layer-0 MLP down_proj component 4707: a "code declaration keyword" detector.

It fires on the first word of a source-code declaration or statement (fn, struct, const,
public, private, static, class, def, void, bool, let, var, ...), more weakly on type names
and import-like words (int, String, import, use, ...), and on the line-comment markers `//`
and `#`. These tokens fire at full strength when they sit in code: after indentation, after a
newline, or after a closing ; { } ) ] : or a modifier such as `public`. The same words in
English prose ("let", "function", "the class of") get only a small value, and so do the
comment markers when they are not at the start of code.
"""

READS = ()

# Words that open a declaration in C-like, Rust, Swift, Python, JS and similar code.
DECLARATION_WORDS = {
    "fn", "func", "def", "function", "struct", "class", "const", "let", "var", "mut", "pub",
    "public", "private", "protected", "static", "final", "void", "bool", "boolean", "impl",
    "interface", "enum", "extern", "async", "double", "float", "fun",
}
# Type names and import-like keywords: they fire, but weaker.
TYPE_WORDS = {
    "int", "String", "string", "long", "uint", "char", "Bool", "import", "use", "export",
    "mod", "type", "namespace", "case",
}
COMMENT_MARKERS = {"//", "#"}
# Modifiers that can sit in front of a declaration.
MODIFIERS = {
    "public", "private", "protected", "static", "pub", "export", "async", "final", "abstract",
}


def in_code(previous: str) -> bool:
    """True when the previous token ends a line, indents, or closes a statement or bracket."""
    if "\n" in previous or (previous.strip() == "" and len(previous) >= 2):
        return True
    if previous.strip() in MODIFIERS:
        return True
    return previous.rstrip().endswith((";", "{", "}", ")", "]", ":"))


def step(carry, prefix, upstream):
    i = prefix.position
    word = prefix.token_strings[-1].strip()
    same_doc = i > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = prefix.token_strings[-2] if same_doc else "\n"
    if word in COMMENT_MARKERS:
        return carry, 0.7 * (1.0 if in_code(previous) else 0.4)
    if word in DECLARATION_WORDS:
        strength = 1.0
    elif word in TYPE_WORDS:
        strength = 0.4
    else:
        return carry, 0.0
    return carry, strength * (1.0 if in_code(previous) else 0.3)

programs.luna:
"""Flag source-code and markup structure using token spelling and line context.

Line-leading declarations, comments, headings, and directives get a positive
estimate; a few technical words also get a smaller estimate away from line
starts. Everything else is predicted as zero.
"""

READS = ()

DECLARATIONS = {
    "abstract", "class", "const", "def", "export", "fn", "from",
    "function", "import", "int", "long", "pub", "public", "static",
    "type", "use", "var", "void",
}

COMMENTS = {"#", "//", "--", "///", "<!--"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before = ""
    else:
        before = carry[1]
    line_start = not before.strip()

    code_line = before.rsplit("\n", 1)[-1]
    if line_start and word in COMMENTS:
        value = 0.72
    elif line_start and word in DECLARATIONS:
        value = 0.70
    elif word == "class" and "public" in code_line:
        value = 0.70
    elif word == "fn" and "pub" in code_line:
        value = 0.70
    elif word == "mut" and "fn" in code_line:
        value = 0.65
    elif line_start and word in {"@@", "CREATE", "ndef"}:
        value = 0.65
    elif word == "TABLE" and "CREATE" in code_line:
        value = 0.65
    elif word == "List" and "public" in code_line:
        value = 0.65
    elif word == "export" and "@@" in code_line:
        value = 0.65
    elif word in {".rs", ".ts"} and "/" in before:
        value = 0.48
    elif word in {"code", "function", "param"}:
        value = 0.18
    else:
        value = 0.0
    if "\n" in token:
        line = token.rsplit("\n", 1)[-1]
    else:
        line = before + token
    return (document, line[-256:]), value

"""A small lexical approximation: a baseline plus extra responses to
'Alternatively', a user message marker, and quoted tool-call field names.
The first value token after a quoted name or command key also gets a response.
It does not try to interpret the rest of the text."""
READS = ()

FIELD_VALUES = {
    "name": 0.54,
    "arguments": 0.63,
    "command": 0.52,
    "path": 0.38,
    "message": 0.32,
}


def step(carry, prefix, upstream):
    words = prefix.token_strings
    token = words[-1]
    if token in ("Alternatively", " Alternatively"):
        return None, 0.45
    if token == "user" and len(words) > 1:
        if words[-2].endswith("<|im_start|>"):
            return None, 0.23
    if token in FIELD_VALUES and len(words) > 1:
        if '"' in words[-2]:
            return None, FIELD_VALUES[token]
    # The word immediately following a quoted JSON tool name or command.
    if len(words) >= 4 and words[-2].endswith('"'):
        if words[-3].endswith(":") and words[-4] in ("name", "command"):
            return None, 0.27
    return None, 0.0115

programs.sol:
"""A token-spelling detector, strongest on ore and core/store/score.

Training examples favor spelling rather than a general meaning: core is
strong, but center and shop are not. The rules distinguish joined fragments,
word beginnings, capitals, separators and common inflections. Short rhymes,
Kore- spellings, and some written core/storage translations respond too.
This deliberately ignores contextual modulation and unrelated weak responses.
"""

READS = ()
ORE_RHYMES = frozenset(('bore', 'chore', 'gore', 'lore', 'moore',
                        'shore', 'sore'))
CORE_FORMS = frozenset(('核心', '芯'))
SHOP_STORAGE_FORMS = frozenset((
    '店', 'お店', '商店', '门店', '儲', '储', '存储', '储存',
))


def response(token):
    word = token.strip()
    lower = word.lower()
    leading_space = token[:1].isspace()
    separator = lower[:1] if lower[:1] in '/._-\\' else ''
    stem = lower[1:] if separator else lower
    capitalized = bool(word) and word != lower

    if stem == 'core':
        if separator in ('-', '_'):
            return -6.7
        if separator in ('/', '.'):
            return -5.4
        if separator == '\\':
            return -3.9
        if word.isupper():
            return -4.7
        if capitalized:
            return -5.0
        return -4.4 if leading_space else -5.8
    if stem == 'cores':
        return -3.8
    if stem.startswith('core') and len(stem) == 5:
        return -3.0
    if stem == 'hardcore':
        return -3.2

    if stem.startswith('store') and stem[5:] in ('', 's', 'd'):
        ending = stem[5:]
        if ending == 'd':
            return -1.1
        value = -2.3 if leading_space else -3.2
        if capitalized and leading_space:
            value -= 0.4
        if ending == 's':
            value += 0.4
        return value
    if stem == 'storing':
        return -1.2
    if stem.startswith('score') and stem[5:] in ('', 's', 'd'):
        ending = stem[5:]
        if ending == 'd':
            return -1.6
        value = -2.1 - (0.3 if capitalized else 0.0)
        if separator == '-':
            value -= 1.1
        return value
    if stem == 'scoring':
        return -1.1

    if lower == 'ore':
        return -2.1 if leading_space else -4.3
    if lower == 'ores':
        return -2.9
    if lower.startswith('ore') and lower[3:] in ('n', 'a', 'an'):
        return -1.8
    if lower in ('ored', 'orer', 'oret', 'orem'):
        return -1.2
    if lower.rstrip('s') in ORE_RHYMES:
        return -2.0
    if lower == 'fore':
        return -0.65
    if lower == 'more':
        if capitalized and not word.isupper():
            return 0.0
        return -0.1 if leading_space else -0.45
    if lower == 'ure':
        return -0.7
    if not leading_space and lower in ('ora', 'ori', 'oric', 'oring'):
        return -0.45
    if lower in ('iore', 'vore'):
        return -1.5
    if lower == 'theorem':
        return -0.6
    if lower == 'kore':
        return -3.8
    if lower in ('korea', 'korean', 'koreans'):
        return -0.6
    if word in CORE_FORMS:
        return -1.9
    if word in SHOP_STORAGE_FORMS:
        return -0.85
    if lower == 'ор':
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

programs.haiku:
"""Fires negatively on the spelling "core" and on the "-ore" words (score, store, ...).

layers.0.mlp.down_proj:4711 is a sparse, lexical component: its activation is set almost
entirely by the current token's spelling, not by context. Its strongest response is to
"core" in any form (core, Core, /core, .core, -core, cores, hardcore), about -4.8. Words
ending in "-ore" with a short onset (score, store, shore, gore, bore, lore, sore, ore, and
their plurals, -ed and -ing forms) get about -2.4. A few "-ore"-like pieces (ure, ored, oren,
oret) get a weak -1. Every other token gets 0.

The program reads only the newest token, lowercases it and drops everything but letters.
"""
import re

READS = ()

CORE_WORDS = {"core", "cores", "hardcore"}
ORE_WORDS = {
    "ore", "ores", "score", "scores", "scored", "scoring",
    "store", "stores", "stored", "storing",
    "shore", "shores", "sore", "gore", "bore", "bored", "lore", "moore",
}
WEAK_WORDS = {"ure", "oren", "ored", "oret", "orent"}


def step(carry, prefix, upstream):
    word = re.sub(r"[^a-z]", "", prefix.token_strings[-1].lower())
    if word in CORE_WORDS:
        value = -4.8
    elif word in ORE_WORDS:
        value = -2.4
    elif word in WEAK_WORDS:
        value = -1.0
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""A modest negative estimate for token pieces spelling 'ore', with a
weaker fallback for 'or'; this is only a rough cue to rare responses."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    if 'ore' in token:
        return None, -0.45
    if 'or' in token:
        return None, -0.10
    return None, 0.0

programs.sol:
"""A mixed lexical signal: wanting/expecting, and the spelling family 'ant'.

Wanting words give large positive values; need, wish and expectation words
are weaker. Some non-English desire words also respond. The 'ant' spelling
family fires even without a desire meaning, especially at a word boundary.
Attached '-ant' fragments are weaker after a long stem. 'Would like' is a
desire rather than a comparison. Most other tokens get zero; 'required'
and 'least' get small negative values. Only the last token is remembered,
and that memory resets at document boundaries.
"""
READS = ()

# Desire words, grammatical forms, and short anticipation/wanting stems.
DESIRE = {
    'want': 4.24, 'wants': 3.65, 'wanted': 2.89, 'wanting': 2.69,
    'wanna': 1.36, 'unwanted': 1.35,
    'need': 0.98, 'needs': 0.83, 'needed': 0.39, 'needing': 0.75,
    'wish': 0.86, 'wishes': 0.80, 'wished': 1.05, 'wishing': 0.60,
    'desire': 0.90, 'desires': 0.79, 'desired': 0.91,
    'desirable': 0.50,
    'expect': 0.93, 'expects': 0.70, 'expected': 0.26,
    'expecting': 0.69, 'unexpected': 0.76,
    'anticipate': 1.65, 'anticipated': 1.04,
    'anticipation': 1.22, 'anticipating': 1.32, 'anticip': 2.05,
    'likes': 0.56,
    # Chinese/Japanese wanting, wishing, and desire.
    '想要': 2.32, '想': 0.89, '我想': 0.84, '不想': 0.98,
    '愿': 1.08, '願': 0.83, '愿意': 0.73,
    '希望': 0.69, '欲': 0.75, '欲望': 0.74, 'ほしい': 0.83,
    # Vietnamese, Spanish, German, and Russian wanting.
    'muốn': 1.34, 'quieres': 1.09, 'wollen': 0.72,
    'хот': 1.18, 'хоч': 1.05, 'хотел': 0.91,
    'хочет': 1.09, 'хотите': 0.61, 'хочу': 0.89,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    boundary = (raw[:1].isspace() or not previous
                or not previous[-1:].isalpha())
    value = DESIRE.get(word, 0.0)

    if word == 'want':
        before = previous.strip()
        if before in {'I', 'i'}:
            value -= 0.34
        elif before in {'You', 'We'}:
            value += 0.65
        elif before.lower() in {'would', 'may', 'might', 'not'}:
            value += 0.30
    if raw.startswith('\t') and word.startswith('want'):
        value *= 0.49

    if word == 'like':
        if previous.strip().lower() in {'would', "'d", '’d'}:
            value = 0.92
    elif word == 'ant':
        if raw.strip() == 'Ant':
            value = 4.35 if raw[:1].isspace() else 4.05
        elif raw.strip().isupper():
            value = 3.25 if boundary else 1.30
        elif raw[:1].isspace():
            value = 4.59
        elif boundary:
            value = 3.40
        else:
            value = 3.8 / (len(previous.strip()) + 0.7)
    elif word == 'ants':
        value = 3.55 if boundary else 0.40
    elif word == 'ante':
        value = 1.65 if boundary else 0.66
    elif word == 'antly':
        value = -0.23
    elif word.startswith('ant') and word not in DESIRE:
        if word.startswith('anti') and len(word) <= 5:
            value = 1.80 if boundary else 1.10
        else:
            value = 1.10 if boundary and len(word) <= 5 else 0.75
    elif 'ant' in word and word not in DESIRE:
        value = 0.65 if len(word) <= 4 else 0.40 if len(word) <= 5 else 0.0
    # Ant/anti echoes across languages: Cyrillic/Katakana, opposition,
    # and Chinese words for the insect.
    elif word in {'ант', 'ан', 'анти', 'アン'}:
        value = 1.90 if word == 'анти' else 1.10
        if word == 'アン':
            value = 0.95
        if word == 'ан':
            value = 1.60 if boundary else 0.28
    elif word in {'抗', '反', '对抗'}:
        value = 1.78 if word == '抗' else 0.92
    elif word in {'蚁', '蚂蚁'}:
        value = 3.40
    elif word == 'required':
        value = -0.25
    elif word == 'least':
        value = -0.36
    return (doc, raw), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 4714: a lexical detector.

It reads only the current token (no memory across positions, so the carry is None).
It fires on the token itself, not on its context:
  * the verb "want" (strongest, ~4.2), and "wants", "wanted", "wanting" (~3-4);
  * the word-initial fragment "ant" / "Ant" that starts a word, as in " antiviral",
    " Antwerp", " antigen", " Antti" (~4.5 with a leading space, ~4.1 capitalised);
    "ant" with no leading space (as in "celebrant") is weak (~0.9); other words
    starting "ant" (" anti", " antique", " anterior") get a weak 1.3;
  * the verbs "need" (~1), "needs" (~0.8), "needed" (~0.4);
  * "desire", "wish", "expect" (~0.9); "expected" is near zero.
Everything else predicts 0.
"""

READS = ()

WANT = {"want": 4.2, "wants": 3.8, "wanted": 2.9, "wanting": 2.8}
NEED = {"need": 1.0, "needs": 0.8, "needed": 0.4}
DESIRE = {"desire": 0.9, "desired": 0.9, "desires": 0.8, "wish": 0.9, "expect": 0.9, "expects": 0.7}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    spaced = raw[:1] == " "
    capital = raw.strip()[:1].isupper()
    if word in WANT:
        value = WANT[word]
    elif word in NEED:
        value = NEED[word]
    elif word in DESIRE:
        value = DESIRE[word]
    elif word == "ant":
        value = 4.1 if capital else (4.5 if spaced else 0.9)
    elif word.startswith("ant") and spaced:
        value = 1.3
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A token-level detector for small Chinese numerals and words about oneness.

The strongest negative response is a bare 一 (one), followed by 二 and 三.
Numerals embedded in words are weaker, especially ordinary counting phrases
and ordinals. Related 'one' and unity word-pieces in other languages also
respond. The Japanese long-vowel mark ー is a separate stroke-shaped trigger.
This approximates the conspicuous responses, not the many small incidental
vocabulary effects. Coefficients are averages estimated from training text.
"""
READS = ()

NUMERALS = {
    '一': -5.5, '二': -2.2, '三': -1.48, '四': -1.3,
    '五': -0.98, '六': -0.82, '七': -0.8, '八': -0.86,
    '九': -0.55, '十': -0.79, '两': -1.25, '兩': -0.94,
    '幺': -0.7, '壹': -1.54,
}
# Common noun classifiers: one person, object, kind, item, place, etc.
CLASSIFIERS = set(
    '名位种種件条條部份家场場只支枚篇套张張颗顆'
    '款座台块塊页頁'
)
# Common grammaticalized expressions: generally, together, alike, everything.
COMMON_ONE_WORDS = {'一般', '一起', '一样', '一樣', '一切', '一边', '一邊'}
UNITY = {'统一', '統一', '同一', '合一', '一致', '一致性', '一律', '一体', '一體'}
ONE_PIECES = {
    '일': -0.92, '한': -0.37, 'ひと': -1.57,
    'một': -0.47, 'nhất': -1.28, 'jed': -0.41,
}
UNITY_WORDS = {
    'unity': -1.0, 'unified': -0.94, 'uniform': -0.24,
    'consistent': -0.4, 'unanim': -0.8, 'singular': -0.15,
}
ENGLISH_NUMBERS = {
    'one': 0.05, 'two': -0.15, 'three': 0.1, 'four': 0.07,
    'five': 0.14, 'six': 0.18, 'seven': 0.2, 'eight': 0.16,
    'nine': 0.2, 'ten': 0.16,
}
QUANTITY_WORDS = {
    '每': -0.66, '每每': -1.3, '几': -0.54, '幾': -0.25,
    '俩': -0.33, '单': 0.35, '單': 0.28,
}


def chinese_compound(s):
    """Discount a written numeral when it is part of a larger word."""
    if '一' in s:
        if s in UNITY:
            return -1.7
        if s in {'在一', 'の一'}:
            return -4.1
        if len(s) == 2 and all(c in NUMERALS for c in s):
            return -1.2 if s.startswith('十') else -3.0
        if '个' in s or '個' in s or '些' in s:
            return -0.18 if len(s) == 2 else -0.08
        if s in COMMON_ONE_WORDS:
            return -0.3
        if s.startswith(('第', '这', '這', '那', '另', '之', '唯')):
            return -0.65 if len(s) == 2 else -0.2
        if len(s) == 2 and s.startswith('一'):
            return -0.4 if s[-1] in CLASSIFIERS else -0.85
        if s.endswith('一'):
            return -1.4
        return -0.3
    if any(c in NUMERALS for c in s):
        if any(c in s for c in '个個年天月次位种種'):
            return 0.0
        return -0.3 if len(s) == 2 else -0.1
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip()
    if s in NUMERALS:
        value = NUMERALS[s]
        # An ordinal prefix may have been split into a separate token.
        if (prefix.position > 0
                and prefix.document_ids[-2] == prefix.document_ids[-1]
                and prefix.token_strings[-2].rstrip().endswith('第')):
            value *= 0.5
    elif s == 'ー':
        value = -0.67
    elif raw == ' един':
        value = -0.76
    elif s in ONE_PIECES:
        value = ONE_PIECES[s]
        if raw.startswith(' ') and s in {'일', '한'}:
            value = -1.67 if s == '일' else -0.92
    elif s.lower() in UNITY_WORDS:
        value = UNITY_WORDS[s.lower()]
    elif s.lower() in ENGLISH_NUMBERS:
        value = ENGLISH_NUMBERS[s.lower()]
    elif s in QUANTITY_WORDS:
        value = QUANTITY_WORDS[s]
    elif s == '致':  # The second character of 一致 ('consistent').
        value = -0.77
    else:
        value = chinese_compound(s)
    return None, float(value)

programs.luna:
"""Predict a sparse negative signal for numeral-like tokens and Japanese ー.

Harvested high-impact examples often center on Chinese/Japanese numerals;
standalone 一 is especially strong, while a few other “one” forms and ー
show smaller negative responses.
"""
READS = ()

CJK_NUMBERS = set("零〇一二三四五六七八九十百千万亿億两兩幺")
LONG_VOWEL = "ー"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "一":
        return None, -6.0
    if any(char in CJK_NUMBERS for char in token):
        return None, -1.0
    if "한" in token or "един" in token.lower():
        return None, -0.8
    if LONG_VOWEL in token:
        return None, -0.8
    return None, 0.0

programs.haiku:
"""Spatial and relational prepositions in technical or narrative prose: where
something sits or happens, or what it is measured against. Examples:
"vertex at (0,0)", "lie on the circle", "cylinder along the x-axis",
"reflection over FG", "flux through the rectangle", "speed with respect to the ground",
"perpendicular to the plane".

The component writes a large positive value on these prepositions, strongest for
"along", "over", "at", "under", "across", "through", and small values elsewhere.
Figurative or idiomatic uses are switched off: "look at", "based on", "rely on",
"went on", "all over the world", "go along with". "to" counts only after a
relational word ("respect to", "parallel to", "perpendicular to", "attached to").
Activation is damped after punctuation and boosted after a copula.

The prediction is the preposition's strength times a context factor:
  * after a copula ("is at", "are on")  -> x1.5
  * after a comma, "and" or "or"        -> x0.5
  * after an idiom verb or "all"        -> x0
"""

READS = ()

# Typical activation when the preposition is used in its locative sense.
LOCATIVE = {
    "over": 1.2, "along": 1.5, "at": 0.75, "under": 0.8, "across": 0.75,
    "onto": 0.6, "inside": 0.5, "through": 0.4, "near": 0.35, "around": 0.35,
    "on": 0.3, "between": 0.3, "throughout": 0.3, "via": 0.3,
}

# "to" after a relational word: "with respect to", "perpendicular to", ...
RELATIONAL = {
    "respect", "parallel", "perpendicular", "proportional", "corresponding",
    "attached", "applied", "assigned", "corresponds", "subjected", "coupled",
}

COPULA = {"is", "are", "was", "were", "be", "been", "being", "am"}
PUNCTUATION = {",", "and", "or", "."}
IDIOM_WORDS = {
    "look", "looking", "looked", "looks", "based", "depending", "depends",
    "rely", "relying", "relied", "focus", "focusing", "focused", "went", "go",
    "all",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "to":
        if len(prefix.token_strings) > 1 and prefix.token_strings[-2].strip().lower() in RELATIONAL:
            return carry, 1.0
        return carry, 0.0
    strength = LOCATIVE.get(word, 0.0)
    if strength and len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2].strip().lower()
        if before in IDIOM_WORDS:
            strength = 0.0
        elif before in COPULA:
            strength *= 1.5
        elif before in PUNCTUATION:
            strength *= 0.5
    return carry, float(strength)

programs.sol:
"""A response to spaces around fragmented text, rather than to a topic.

Spaces after multi-piece words, numbers, hashes, or NUL-corrupted text receive
negative values. Short space-prefixed letters/byte fragments also respond;
Greek prose is distinguished from math by recent Greek-letter density.
Most other tokens receive zero. Levels approximate training averages; small
word-specific fluctuations are deliberately left unmodeled.
"""
import math
import unicodedata as ud
from functools import lru_cache

READS = ()
# Vocabulary metadata: space + an unfinished UTF-8 character (bytes in comments).
GREEK_STARTS = {7851, 17383}                # CE, CF
EARLY_THREE_BYTE_STARTS = {                # E0/E1: Indic, Ethiopic, Greek
    27982, 86089, 14925, 35178, 69033, 70597, 93255, 89434, 94491,
}
KANA_STARTS = {17587, 20711}               # E3 82, E3 83
HANGUL_RANGE_STARTS = {8620, 5140, 3315, 10764}   # EA, EB, EC, ED


@lru_cache(maxsize=8192)
def script(text):
    for ch in reversed(text):
        if ch.isalpha():
            name = ud.name(ch, '')
            for kind in ('GREEK', 'ARABIC', 'CYRILLIC', 'HANGUL', 'CJK', 'LATIN'):
                if kind in name:
                    return kind
    return ''


def boundary(previous, tail, pieces, age):
    word = previous.strip()
    if not word:
        return 0.0
    if '\x00' in tail or (len(tail) >= 12 and any(c.isalpha() for c in tail)
                         and all(c in '0123456789abcdefABCDEF' for c in tail)):
        return -2.2
    if pieces >= 4:
        value = -1.3 if word.isdigit() else -0.85
        if len(word) == 1 and script(word) == 'LATIN':
            value = -1.15
    elif word[-1:].isdigit():
        value = -0.45
    elif word.isupper():
        value = -0.5
    elif pieces <= 1:
        value = -0.02
    elif word[-1:].isalpha():
        value = -0.8 if len(word) == 1 else -0.35
    else:
        value = -0.15
    # Sentence punctuation weakens the preceding fragmentation signal.
    if previous.endswith(','):
        value = -0.1 if pieces >= 4 else 0.04
    elif previous.endswith(':'):
        value = -0.18 if pieces >= 4 else -0.03
    elif previous.endswith('.'):
        value = -0.36 if pieces >= 4 else -0.1
    if script(previous) in ('CJK', 'HANGUL'):
        value = min(-0.05, value + 0.4)
    return value - 0.5 * math.exp(-age / 6) * (pieces >= 2)


def short_start(word, token_id, recent, pressure):
    kind = script(word)
    if kind == 'GREEK' or word == '�':
        greek = sum('GREEK' in ud.name(c, '') for c in recent)
        letters = sum(c.isalpha() for c in recent)
        prose = greek >= 3 and greek >= 0.6 * letters
        if kind == 'GREEK':
            return -1.33 if prose else 0.015
        if token_id in GREEK_STARTS:
            return -2.25 if prose else -0.45
        if token_id in EARLY_THREE_BYTE_STARTS:
            return -1.7 - 1.75 * min(recent.count('�') / 20, 1)
        if token_id in KANA_STARTS:
            return -1.0
        if token_id in HANGUL_RANGE_STARTS:
            return -0.75
        return -0.25 - 0.02 * min(recent.count('�'), 20)
    if kind == 'ARABIC':
        return -0.52
    if kind == 'LATIN':
        return 0.02 + 0.04 * pressure - 0.13 * min(pressure, 0)**2
    if kind == 'CYRILLIC':
        return 0.07 + 0.18 * pressure - 0.05 * min(pressure, 0)**2
    if word == '\\':
        return -0.176
    if word == '\xa0':
        return -0.272
    if not word.isalpha():
        return 0.02 + 0.025 * pressure - 0.065 * min(pressure, 0)**2
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail, pieces, recent, age = '', '', 0, '', 0
    else:
        _, previous, tail, pieces, recent, age = carry
    value = 0.0
    if token.startswith(' '):
        word = token[1:]
        pressure = boundary(previous, tail, pieces, age)
        if not word:
            value = pressure
        elif len(word) == 1:
            value = short_start(word, prefix.token_ids[-1], recent, pressure)
        elif word.isspace():
            value = 0.01 - 0.04 * pressure - 0.08 * min(pressure, 0)**2
    # Remember only the last uninterrupted run and a short text window.
    if not token or token[-1].isspace():
        tail, pieces = '', 0
    elif any(c.isspace() for c in token):
        tail, pieces = token.split()[-1][-80:], 1
    else:
        tail, pieces = (tail + token)[-80:], pieces + 1
    recent = (recent + token)[-60:]
    return (doc, token, tail, pieces, recent, age + 1), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 4718, as a small lexical detector.

Plain-terms summary. The component is mostly quiet, with rare large values. The classes
below carry most of what it does:
- the first token of each document (about +0.15);
- "in" used as a preposition inside a passage of non-English text (about +0.14); the same word
  in English text ("logged in", "sign in") stays near 0;
- other English-spelled content words inside non-English text (about +0.03). The same words in
  English text stay near 0;
- the role word "user" (about +0.13) and the chat opener "<|im_start|>" (about +0.03);
- the bare token "n" (about -0.27), and the tool tags "<tool_call>" and "<tool_response>"
  (about -0.14);
- foreign function words such as "la", "le", "se", "para" (about -0.03).

"Non-English context" means fewer than 10% of the 16 preceding tokens in the same document are
English function words. Everything else predicts 0. The values are class means, least-squares
fitted by hand on about 2000 training rows. This explains about 5-6% of the variance. A
per-token lookup table of about 10,000 tokens would explain about 13%, but it has no concept
behind it, so this program keeps only the classes.
"""

READS = ()

# Common English function words; "English context" means these are rare in the recent text.
EN_FUNCTION = frozenset(
    "the and is of to that with for it was are be this on as you have not by at from or an "
    "but they we he she his her their which will would can there been has had".split()
)

# Common function words of Romance, German and Scandinavian languages.
FOREIGN_FUNCTION = frozenset(
    "la le se es al na para aus un por de di che und der die het en que el los las du des "
    "da lo gli il della nie jest och som og er zijn auf mit sich ist nicht sur".split()
)


def _foreign_context(prefix):
    """True if, among the 16 tokens before this one in the same document, English function
    words are rare (under 10%)."""
    words = prefix.token_strings
    docs = prefix.document_ids
    recent = []
    for i in range(len(words) - 2, max(-1, len(words) - 18), -1):
        if docs[i] != docs[-1]:
            break
        recent.append(words[i].strip().lower())
    if not recent:
        return False
    return sum(w in EN_FUNCTION for w in recent) / len(recent) < 0.1


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    core = tok.strip().lower()
    docs = prefix.document_ids
    if prefix.position == 0 or docs[-1] != docs[-2]:
        value = 0.155  # first token of a document
    elif tok == "<|im_start|>":
        value = 0.03
    elif tok == "user":
        value = 0.13
    elif tok == "n":
        value = -0.27
    elif tok in ("<tool_call>", "<tool_response>"):
        value = -0.14
    elif tok == " in" and _foreign_context(prefix):
        value = 0.14  # "in" as a preposition in non-English text
    elif core in FOREIGN_FUNCTION:
        value = -0.03
    elif (
        core.isascii()
        and core.isalpha()
        and len(core) >= 2
        and core not in EN_FUNCTION
        and _foreign_context(prefix)
    ):
        value = 0.03  # English-spelled word inside non-English text
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Approximate a rare signed response to a few people-and-organization words.

The harvest shows negative pulses on English role/group nouns, and positive
pulses on agency/personnel/initiative terms. This lexical rule leaves other
positions at zero; it is a compact approximation, not a general word detector.
"""

READS = ()

ENGLISH_ROLES_AND_GROUPS = frozenset({
    "member", "members", "team", "officer", "director", "minister",
    "professor",
})
CHINESE_PEOPLE_TERMS = frozenset({"人员", "专家"})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in ENGLISH_ROLES_AND_GROUPS:
        return None, -0.72
    if word == "agency":
        return None, 0.83
    if word in CHINESE_PEOPLE_TERMS:
        return None, 0.85
    if word == "积极性":
        return None, 0.75
    return None, 0.0

programs.sol:
"""A token-local 'pl' spelling detector, strongest on unfinished fragments.

Longer words containing 'pl' have smaller responses. Familiar weak-response
word families are suppressed. Cyrillic and a few other phonetic spellings,
bare 'bl', and the implication sign get additional small rules. There is no
context dependence, and all unrecognized tokens produce zero.
"""
READS = ()

WEAK_FAMILIES = (
    'people', 'example', 'sampl', 'simple', 'simply', 'apply',
    'applied', 'applies', 'applic', 'complet', 'complex', 'multiple',
    'employ', 'explor', 'explicit', 'supply', 'suppli', 'coupl',
    'apple', 'principl', 'triplet', 'plus', 'planet', 'deeply', 'upload',
)


def response(token):
    word = token.strip().lstrip('._-/(')
    low = word.lower()
    if low.endswith('pl'):
        if low == 'pl':
            value = 5.0
        elif low in ('impl', 'spl'):
            value = 6.0
        elif low in ('ipl', 'mpl', 'compl'):
            value = 4.4
        else:
            value = max(0.9, 5.4 - 0.6 * len(low))
        if word.istitle():
            value *= 0.84
        if token.startswith(('.', '_', '/')):
            value *= 0.85
        return value
    if 'pl' in low:
        if any(root in low for root in WEAK_FAMILIES):
            return 0.08
        if 'play' in low and 'playful' not in low:
            return 0.16
        if 'implem' in low or 'replac' in low:
            return 1.3
        return 0.8
    if low.endswith('пл'):
        return 2.6
    if 'пл' in low:
        return 0.95
    if low in ('bl', 'бл'):
        return 0.6
    if '⇒' in token:
        return 0.54
    if word == '플' or word.startswith('プラ'):
        return 3.0
    if word.startswith(('プリ', 'プレ', 'ปล')):
        return 1.3
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

programs.haiku:
"""Fires on the number six or seven, written in any common form.

Layer 0's MLP output has one slice (this component) that reads the current token's identity
and not its context. It is switched on by:
  - the digits 6 and 7 (also fullwidth ６ and ７), and the words six, seven, sixth, seventh,
    and the Chinese characters 六 and 七: about 1.05 each;
  - the month names June and July, which are the 6th and 7th months: about 0.7 each.
Every other token gives 0. Each position is scored from its own token alone, so the
program keeps no state between positions.
"""

READS = ()

SIX_OR_SEVEN = {"6", "7", "６", "７", "six", "seven", "sixth", "seventh", "六", "七"}
MONTHS_6_7 = {"June", "July"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in SIX_OR_SEVEN:
        return carry, 1.05
    if word in MONTHS_6_7:
        return carry, 0.7
    return carry, 0.0

programs.luna:
"""Approximate sparse responses to adjectives/adverbs in degree constructions."""

READS = ()

DEGREE_CUES = {
    "how", "as", "more", "most", "less", "least", "very", "rather",
    "quite", "too", "so", "really", "especially", "not",
}

IRREGULAR_DESCRIPTORS = {
    "much", "hard", "easy", "well", "fast", "slow", "long", "longer",
    "short", "wide", "tight", "early", "likely", "unlikely", "good", "bad",
}


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    word = prefix.token_strings[-1].strip().casefold()
    previous = prefix.token_strings[-2].strip().casefold()
    descriptor = word in IRREGULAR_DESCRIPTORS or word.endswith(
        ("ly", "ous", "ive", "able", "ible", "ful", "less", "ent", "al")
    )
    cue = previous in DEGREE_CUES or previous.endswith("ly")
    return None, 0.45 if cue and descriptor else 0.0

programs.sol:
"""Approximate the local continuation feature around a/an and the letter A.

Vowel-like continuations after a, and consonant-like continuations after an,
usually receive positive values. Many familiar article constructions
receive negative values, especially 'a certain', 'a particular', and 'a time'.
This is not a general grammaticality checker: notation, capitals, quotations,
and word pieces have separate rules. Related Romance function words produce
weaker responses before vowels.

Two previous tokens and decaying English/Romance/German cue counts are
retained. The counts calibrate uncertain word onsets; documents reset all state.
Unrecognized cases are zero. Grouped phrase weights omit finer lexical variation.
"""
import unicodedata

READS = ()

SPECIFIC_MODIFIERS = {'given', 'specific', 'different', 'general', 'similar'}
AMOUNT_NOUNS = {'lot', 'piece', 'bit', 'kind', 'series'}
DEGREE_WORDS = {'very', 'more', 'much', 'pretty', 'relatively', 'well',
                'considerable', 'major', 'full'}
SIZE_QUALITY = {'whole', 'small', 'huge', 'great'}

A_PHRASES = {
    'certain': -2.5, 'particular': -1.4, 'particularly': -1.4,
    'time': -1.2, 'variety': -1.0, 'way': -0.9, 'distance': -0.9,
    'recent': -0.9, 'new': -0.2, 'while': -0.4, 'unit': 0.6,
}
A_PHRASES.update(dict.fromkeys(SPECIFIC_MODIFIERS, -0.8))
A_PHRASES.update(dict.fromkeys(AMOUNT_NOUNS, -0.55))
A_PHRASES.update(dict.fromkeys(DEGREE_WORDS, -0.6))
A_PHRASES.update(dict.fromkeys(SIZE_QUALITY, 0.4))
FUNCTION_WORDS = frozenset('a an and or is are in of at as on to it if'.split())
ENGLISH = frozenset('the and of to for with that this it is are was be'.split())
FOREIGN_CUES = frozenset((
    'que para em uma una los las del com con como por el '
    'da de do das dos na ao os su es des du une il della '
    'der den die das dem des und ist nicht ein eine einer '
    'einem einen mit auf zu von im als sich auch'
).split())
# Common written-vowel prefixes pronounced with an initial /y/ sound.
YOO_PREFIXES = (
    'unit', 'univ', 'union', 'unif', 'uniq', 'unil', 'unid', 'unic',
    'unip', 'unison', 'use', 'usu', 'util', 'uten', 'uter', 'utop',
    'urin', 'urani', 'urea', 'ureth', 'urol', 'ubiq',
)
QUOTES = '\"\'“‘`'
MATH_SIGNS = '=^|_+*-<>/%&'


def vowel_like(text):
    """Rough English onset, ignoring accents, with common sound exceptions."""
    t = unicodedata.normalize('NFD', text.lower())
    t = ''.join(c for c in t if not unicodedata.combining(c))
    if t.startswith(('hour', 'honest', 'honor', 'heir')):
        return True
    if t.startswith(YOO_PREFIXES + ('eu', 'one', 'once')):
        return False
    return bool(t) and t[0] in 'aeiou'


def after_a(s, previous, english, foreign):
    word = s.strip().lower()
    full = previous.startswith(' ')
    capital = previous.strip().isupper()
    scale = 1.0 if full else 0.55
    if word in A_PHRASES:
        return A_PHRASES[word] * (1.0 if full or capital else 0.75)
    if not word:
        return -0.15 if full or capital else -0.04
    if word[0] in '.):;、' and not (word[0] == '.' and len(word) > 1):
        return -0.5 if full or capital else -0.25
    if word[0] in QUOTES:
        return 0.72 * scale
    if word[0] in ',' + MATH_SIGNS or word[0] == '.':
        return 0.43 * scale
    if word == 'a':
        return 1.3 if capital else 1.6 * scale
    if capital and word in ('to', 'of'):
        return -0.25
    if word == 'such':
        return 1.8 * scale
    if word in FUNCTION_WORDS and s.strip().islower():
        return 0.5 if capital else 1.0 * scale
    if vowel_like(word):
        if not s.startswith(' '):
            # Joined spellings such as aer-, aur-, austr- are not new words.
            value = -0.5 if word.startswith(('er', 'ur', 'ust', 'uct')) else 1.2
            return value * (0.75 if capital else scale)
        if s.strip().isupper():
            return 1.1
        if s.strip()[0].isupper():
            return 1.4 * (1.0 if full or capital else 0.55)
        if capital:
            return 0.6
        if not full:
            return 0.5
        if english > foreign + 0.3 and len(word) > 3:
            return 2.35
        return 0.6 if foreign > english + 0.3 else 1.3
    if s.startswith(' ') and s.strip().isupper() and word.isalpha():
        return (1.0 if s.strip()[0] in 'FHLMNRSX' else 0.25) * scale
    if word.startswith(YOO_PREFIXES):
        return 0.25 * scale
    if word.isdigit():
        return -0.2 if capital else 0.35 * scale
    if len(word) == 1:
        return 0.5 * scale
    return -0.25 if capital else -0.06


def after_an(s, previous, english, foreign):
    word = s.strip().lower()
    full = previous.startswith(' ')
    if word in ('other', 'enough'):
        return 0.8 if full else 0.4
    if not word or word[0] in QUOTES + '$' + MATH_SIGNS:
        return 0.65 * (1.0 if full else 0.55)
    if not word[0].isalpha():
        return 0.0
    if s.strip().isupper():
        return -0.2 if word[0] in 'aeio' else 0.4
    if vowel_like(word):
        return -0.23
    if not full and previous.strip() != 'An':
        return 0.45
    if (s.startswith(' ') and len(word) > 3 and word[0] not in 'aeiou'
            and english > foreign + 0.3):
        return 1.8
    return 0.95 if s.startswith(' ') else 0.65


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    word = s.strip().lower()
    if carry is None or carry[0] != doc:
        previous, before_previous, english, foreign = '', '', 0.0, 0.0
    else:
        _, previous, before_previous, english, foreign = carry
    p = previous.strip().lower()
    out = 0.0
    if not previous:
        if word == 'a':
            if s == ' a':
                out = 2.1
            elif s == ' A':
                out = 1.54
            else:
                out = 1.31 if s == 'A' else 0.81
        elif word in ('à', 'á', 'â'):
            out = 1.0
    elif p == 'a':
        out = after_a(s, previous, english, foreign)
    elif p == 'an':
        out = after_an(s, previous, english, foreign)
    elif p == 'variety' and before_previous.strip().lower() == 'a' and word == 'of':
        out = -0.98
    elif p in ('la', 'della', 'nella', 'da', 'à') and vowel_like(word):
        out = 0.9 if p in ('della', 'nella') else 0.4
    elif p in ('de', 'di', 'le', 'il', 'del', 'du') and vowel_like(word):
        if s.startswith(' '):
            out = 0.6 if p == 'il' else 0.25
        else:
            out = 0.5 if p in ('de', 'del') else 0.15
    elif p.endswith('a') and not p.startswith('<|') and vowel_like(word):
        out = 0.15 if len(p) <= 3 else 0.06
    boundary = s.startswith(' ') or not previous or previous[-1:].isspace()
    english = 0.92 * english + (boundary and word in ENGLISH)
    foreign = 0.92 * foreign + (boundary and word in FOREIGN_CUES)
    return (doc, s, previous, english, foreign), float(out)

programs.haiku:
"""layers.0.mlp.down_proj:4725 — an "a/an" article-agreement detector.

What it does: this component reads the word right after an article. It is positive when the
article does not fit the word's first sound, i.e. "a" before a vowel-initial word ("a easy",
"a important") or "an" before a consonant-initial word ("an public"). It is strongly negative
for "a" before the phrase words that routinely follow "a" ("a certain", "a particular",
"a variety of", "a lot of", "a bit", "a way", "a time", "a given"). It is ~0 everywhere else.
A bare "a" (or "A") as the first token of a document is also strongly positive.

Why: the sign pattern is a mismatch signal: the article's expected form versus the next word's
initial vowel/consonant. The program ignores the rest of the context.
"""

READS = ()

VOWELS = "aeiou"
A_FORMS = {" a", " A", "a", "A"}
AN_FORMS = {" an", " An", "an", "An"}
# Words that follow "a" in fixed phrases: "a certain", "a lot of", "a bit", "a way to", ...
PHRASE_WORDS = {" certain", " particular", " specific", " given", " different", " variety",
                " way", " time", " lot", " bit", " piece", " very", " pretty", " general"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        # The first token of a document: a bare article has no context, so the token alone decides.
        return None, (2.1 if cur == " a" else 1.3 if cur == "A" else 0.0)
    prev = prefix.token_strings[-2]
    first = cur.strip()[:1].lower()
    if prev in A_FORMS:
        if first and first in VOWELS:
            return None, 0.7  # "a" before a vowel-initial word: mismatch
        if cur in PHRASE_WORDS:
            return None, -1.0  # "a certain", "a lot": fixed phrase
        return None, -0.1
    if prev in AN_FORMS:
        if first and first.isalpha() and first not in VOWELS:
            return None, 0.5  # "an" before a consonant-initial word: mismatch
        return None, -0.2  # "an" before a vowel: the normal case, slightly negative
    return None, 0.0

programs.luna:
"""Recognize words about combining parts or relating them as a whole.

The larger value is for explicit mixing, joining, or merging; the smaller
value marks related cues such as both, between, integral, or overall. The
word cues are a readable approximation, not a claim about every occurrence.
"""
READS = ()

MIXING = ("combin", "blend", "merg", "mix", "conjunt", "联合")
JOINING = ("collabor", "crossov", "joint", "intersect", "integrat")
RELATED = (
    "both", "between", "together", "cooper", "connect", "relation",
    "interact", "link", "union", "arrang", "collect", "assembl",
    "comprehens", "overall", "integral", "group", "ensemble",
    "composite", "compound", "aggregate", "utiliz", "conjunto",
    "вместе", "cùng", "mista", "смес",
)
OTHER_LANGUAGES = (
    "共建", "集", "搭", "不合", "可通过", "共同", "混合", "結合",
    "連携", "両方",
)


def _cue(word):
    w = word.casefold()
    if any(root in w for root in MIXING):
        return 1.8
    if any(root in w for root in JOINING):
        return 1.1
    if any(root in w for root in RELATED):
        return 0.65
    if any(root in w for root in OTHER_LANGUAGES):
        return 0.65
    return 0.0


def _cjk(char):
    code = ord(char)
    return (
        0x2E80 <= code <= 0x9FFF
        or 0xF900 <= code <= 0xFAFF
        or 0x3040 <= code <= 0x30FF
        or 0xAC00 <= code <= 0xD7AF
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, recent = "", ()
    else:
        _, word, recent = carry

    token = prefix.token_strings[-1]
    piece = token.strip()
    direct = _cue(piece)

    # Leading whitespace begins a new word; adjacent pieces may form one word.
    if token[:1].isspace():
        if word:
            recent = (recent + (word.casefold(),))[-3:]
        word = ""

    for ch in token:
        if ch == "\ufffd":
            continue
        if ch.isalpha() and not _cjk(ch):
            word += ch
        elif ch.isalpha():
            # CJK writing has no spaces between words: use this token itself.
            if word:
                recent = (recent + (word.casefold(),))[-3:]
            word = ""
        elif ch in "'-’" and word:
            word += ch
        else:
            if word:
                recent = (recent + (word.casefold(),))[-3:]
            word = ""

    value = max(direct, _cue(word))
    bare = piece.casefold()
    if bare == "of":
        for prev in recent:
            if "intersect" in prev:
                value = max(value, 1.2)
            elif any(root in prev for root in ("integr", "combin", "union")):
                value = max(value, 0.65)
            elif "ratio" in prev:
                value = max(value, 0.3)

    return (doc, word, recent), float(value)

programs.sol:
"""Predict salient negative responses to short phrase completions.

The main pattern is the anaphoric action phrase 'do so'. Selected other
complements of 'do', measurement expressions, unit tests, confidence phrases,
and split documentation words receive weaker negative values. These patterns
explain conspicuous training responses, not the many small lexical effects.
History resets between documents. Unrecognized tokens get zero, except for a
small negative background on 'so'.
"""
READS = ()
DO_FORMS = {'do', 'doing', 'done', 'does', 'did'}
DO_COMPLEMENTS = {
    'nothing': -0.8,
    'something': -0.6,
    'everything': -0.5,
    'anything': -0.45,
    'whatever': -0.5,
    'what': -0.3,
    'things': -0.38,
    'business': -0.43,
    'well': -0.45,
    'better': -0.5,
    'correctly': -0.6,
    'differently': -0.55,
    'with': -0.2,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, before = '', ''
    else:
        _, prev, before = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word == 'so':
        value = -0.06
        if prev == 'do':
            value = -1.89
        elif prev == 'doing':
            value = -1.8
        elif prev in ('does', 'did', 'done'):
            value = -1.2
        elif prev in ('or', 'even'):
            value = -0.5
        elif prev == 'it' and before in DO_FORMS:
            value = -0.8
        elif prev in ('say', 'said'):
            value = -0.4
        elif prev and all(not c.isalnum() for c in prev):
            value = -0.02
    elif prev in DO_FORMS and word in DO_COMPLEMENTS:
        value = DO_COMPLEMENTS[word]
    elif prev == 'this' and before == 'done' and word == 'correctly':
        value = -0.55
    elif word == 'freedom' and prev == 'of' and before in ('degree', 'degrees'):
        value = -0.96
    elif word in ('fahrenheit', 'celsius') and prev in ('degree', 'degrees'):
        value = -0.88 if word == 'fahrenheit' else -0.5
    elif word in ('test', 'tests', 'testing') and prev == 'unit':
        value = -0.5
    elif word in ('confidence', 'confident') and prev == '%':
        value = -0.43 if word == 'confidence' else -0.25
    elif not token.startswith(' ') and prev.endswith('doc'):
        if word in ('string', 'strings'):
            value = -0.72
    elif not token.startswith(' ') and prev == 'do':
        if prev + word in ('doctest', 'doctype', 'doxygen'):
            value = -0.8
    return (doc, word, prev), value

programs.luna:
"""Approximate a few recurring phrase completions with small negative signals.

The clearest large response is “do so”; the smaller rules cover other
ordinary completions and collocations seen in the harvested examples. This
is a text heuristic, not a general account of the component.
"""
import re

READS = ()

DO_WORDS = {"do", "does", "did", "doing", "done"}
DO_COMPLEMENTS = {
    "well", "differently", "nothing", "something", "everything", "not",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before = ""
    else:
        before = carry[1]

    words = re.findall(r"[^\W\d_]+", before.casefold())
    previous = words[-1] if words else ""
    previous_two = tuple(words[-2:])
    current = prefix.token_strings[-1].strip().casefold()
    value = 0.0

    if current == "so":
        value = -1.55 if previous in DO_WORDS else -0.50
    elif current in DO_COMPLEMENTS and previous in DO_WORDS:
        value = -0.56
    elif current == "correctly" and (
        previous == "done" or previous_two == ("done", "this")
    ):
        value = -0.57
    elif current == "freedom" and previous_two in {
        ("degree", "of"), ("degrees", "of")
    }:
        value = -0.95
    elif current == "fahrenheit" and previous == "degrees":
        value = -0.88

    tail = (before + prefix.token_strings[-1])[-100:]
    return (doc, tail), float(value)

programs.sol:
"""Token-form approximation, not a full lexical lookup.

Ordinary separators and common grammatical tokens stay near zero. Acronyms,
short capitalized tokens, attached code names, and non-Latin word pieces get
negative class averages. Conventional filename suffixes and conversation
markers have stronger calibrated responses. The lexical-family rules match
spellings, not meanings. Individual-token exceptions remain unexplained;
using broad classes keeps the program smaller than a full lexical table.
No token history is used.
"""
READS = ()

FORMAT_MARKERS = {
    '<tool_call>': 0.08, '</tool_call>': -1.20,
    '<tool_response>': -1.63, '</tool_response>': -0.10,
    '<think>': 0.64, '</think>': -0.28,
    '<|im_start|>': -0.13, '<|im_end|>': -0.09,
    '<|endoftext|>': -0.03,
}
FILE_SUFFIXES = {'.go': -1.88, '.rs': -1.06, '.ts': -0.77, '.md': -0.93}
GRAMMAR = set('''
    a an the this that these those each every either neither all any some no
    both few many much more most other such what which who whom whose where
    when why how i me my mine we us our ours you your yours he him his she her
    hers it its they them their theirs am is are was were be been being have
    has had having do does did doing can could may might must shall should
    will would of to in on at by for from with without about above below under
    over between among before after during through into onto upon within
    throughout against around along across behind beyond until since per than
    as like up down out off and or but nor so yet if unless although though
    while whereas because whether however then else also too even only just
    not yes
    de del la le les los las el il lo un une una des du di da en et que qui ce
    se sa ses son sur pour par avec dans est sont mais ou au aux ne pas plus
    nous vous leur lui elle elles ils on je es por con para pero su sus al
    como si y e do dos das um uma em com sem não ao seu sua os as mas é
    und der die das den dem ein eine zu von mit auf im an am bei aus für nicht
    als auch sich er sie wir ihr du ich nach was wie wer wenn aber oder zum zur
    в на и а но с к по у о из за от до не ни то это что как ли же мы вы я он она
    оно они его ее их ты для или при без во об все еще если так был была были
    self true false return class def public private static const null nil var
    let int str string bool function func import package new try catch break
'''.split())
CHINESE_GRAMMAR = set('我你他她它这那這是了但也还還又') | {'但是'}
JAPANESE_PARTICLES = set('の が は を に と も へ で よ ね には では です ます'.split())
NOUN_ENDINGS = ('tion', 'tions', 'sion', 'sions', 'ment', 'ments',
                'ness', 'ity', 'ities', 'ance', 'ence')


def activation(raw):
    if raw in FORMAT_MARKERS:
        return FORMAT_MARKERS[raw]
    if raw in FILE_SUFFIXES:
        return FILE_SUFFIXES[raw]
    s = raw.strip()
    low = s.lower()
    boundary = raw[:1].isspace()
    if raw == '=' or raw.endswith((')=', '}=')):
        return -0.41
    if '\r\n' in raw:
        return -0.51 if raw.count('\r\n') == 1 else -0.90
    if len(s) > 3 and len(set(s)) == 1 and not s.isalnum():
        return -0.48 if len(s) > 15 else -0.18
    if s in CHINESE_GRAMMAR:
        return -0.56
    if s in JAPANESE_PARTICLES:
        return 0.07
    if s in {'した', 'して', 'ため', 'など'}:
        return -0.62
    if s == '一':
        return -0.70
    if s in {'kB', '/cm'}:
        return -1.33
    n = sum(c.isalpha() for c in s)
    if not n:
        return -0.07 if '\ufffd' in s else 0.0
    if s.startswith(('.get', '.Get')):
        return -0.67
    if s.startswith(('.Print', '.WriteLine')):
        return -0.88
    if s.startswith('.'):
        data_suffixes = {'.js', '.json', '.yaml', '.yml', '.html', '.xml', '.txt'}
        return 0.03 if s in data_suffixes else -0.21
    if s.startswith('/'):
        return -1.71 if s == '/tests' else -0.19
    if s.startswith(('_', '-')):
        return -0.14
    if not s.isalpha():
        return -0.04 if s.startswith(("'", '’')) else -0.18
    if low in {'work', 'works', 'worked'}:
        return -0.59
    if low in {'perhaps', 'maybe', 'probably', 'possibly'}:
        return -0.64 if low == 'perhaps' else -0.30
    if low in GRAMMAR:
        return 0.0
    if s.isascii():
        if n == 1:
            return 0.02
        if s.isupper():
            return -0.19
        if not s.islower() and not s.istitle():
            return -0.43
        if n > 5 and low.endswith(NOUN_ENDINGS):
            return 0.04 if boundary else -0.02
        if s.istitle():
            if n <= 3:
                return -0.33 if n == 2 else -0.17
            return -0.10 if boundary else -0.03
        if n <= 3:
            if boundary:
                return -0.14 if n == 2 else -0.07
            return 0.02 if n == 2 else -0.04
        return -0.04
    if any('\u3400' <= c <= '\u9fff' for c in s):
        return -0.02 if n == 1 else -0.17
    if any('\u0400' <= c <= '\u052f' for c in s):
        return 0.0 if n == 1 else (-0.40 if boundary else -0.05)
    if any('\u3040' <= c <= '\u30ff' for c in s):
        return -0.07 if n == 1 else -0.26
    return -0.07 if n == 1 else (-0.28 if boundary else -0.16)


def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

"""Approximate a word-form detector, not a sentiment detector.

Predict negative activation for -ive adjectives and their derivatives,
plus related foreign suffix fragments. Isolated suffix pieces are stronger;
plurals, adverbs and abstract nouns are usually weaker. Calibrate common
-ive words separately and exclude lookalike verbs. Use only the current token,
returning zero elsewhere; context and other adjective forms are not modeled.
"""
READS = ()

NON_DERIVATIONS = frozenset('''
five give live drive arrive archive hive dive thrive strive forgive
receive believe deceive conceive olive derive contrive
alive survive revive perceive
waive wife knife wive knive vive nive rive
'''.split())

# Strengths of familiar members of the -ive word family.
WORD_STRENGTH = {
    'active': 1.1, 'negative': 3.3, 'positive': 2.0,
    'effective': 2.9, 'relative': 2.7, 'alternative': 2.4,
    'administrative': 2.0, 'derivative': 2.0, 'comprehensive': 2.5,
    'representative': 3.7, 'native': 4.2, 'creative': 4.3,
    'competitive': 4.6, 'inclusive': 5.2, 'narrative': 4.3,
    'descriptive': 5.6, 'comparative': 5.4, 'intensive': 4.0,
    'intuitive': 2.2, 'sensitive': 1.4, 'executive': 1.6,
    'recursive': 1.6, 'extensive': 1.6, 'respective': 0.65,
    'perspective': 1.3, 'expensive': 1.1, 'qualitative': 2.6,
    'initiative': 2.5, 'defective': 1.1, 'excessive': 2.1,
    'consecutive': 0.2, 'massive': 0.6, 'impressive': 0.5,
    'automotive': 0.65, 'successive': 0.9, 'inexpensive': 0.8,
    'interactive': 2.0, 'insensitive': 1.6, 'legislative': 2.0,
    'passive': 1.6, 'inactive': 1.0, 'motive': 1.2,
    'decisive': 1.4, 'detective': 1.4, 'ineffective': 1.7,
    'immersive': 5.0, 'imaginative': 5.0, 'responsive': 4.2,
}


def response(token):
    word = token.lstrip(' -_./').lower()
    ending = 'base'
    if word.endswith('ness'):
        word, ending = word[:-4], 'ness'
    elif word.endswith('ly'):
        word, ending = word[:-2], 'ly'
    elif word.endswith('ity'):
        word, ending = word[:-3] + 'e', 'ity'
    elif word.endswith('s'):
        word, ending = word[:-1], 's'
    if not word.isalpha() or word in NON_DERIVATIONS:
        return 0.0
    if word == 'против':
        return 0.0
    if word == 'эффектив':
        return -1.3
    if word.endswith('ceive'):
        return 0.0
    if not word.endswith('ive'):
        # Related adjective and agent-noun derivational fragments.
        for suffix, strength in (
            ('ativa', 3.1), ('ativo', 2.0), ('ativ', 2.3),
            ('atif', 1.8), ('iva', 0.6), ('ivo', 0.7), ('iv', 0.5),
            ('ектив', 3.6), ('тив', 1.4), ('ив', 0.6),
            ('итель', 1.2), ('атель', 1.2),
        ):
            if word.endswith(suffix):
                return -strength
        return 0.0

    # Stand-alone pieces of the productive suffix.
    if word in ('ative', 'itive', 'ive'):
        strengths = {'ative': 6.5, 'itive': 4.8, 'ive': 2.7}
        factors = {'base': 1.0, 's': 0.65, 'ly': 0.55,
                   'ness': 0.8, 'ity': 0.4}
        if word == 'ative' and ending == 's':
            return -5.3
        if word == 'ive' and ending == 's':
            return -1.3
        if word == 'ative' and ending == 'ly':
            return -2.6
        return -strengths[word] * factors[ending]

    strength = WORD_STRENGTH.get(word)
    if strength is None:
        strength = 3.6 if word.endswith('ative') else 3.2
        if not token[0].isspace():
            strength += 0.5
    factor = {'base': 1.0, 's': 0.7, 'ly': 0.65,
              'ness': 0.8, 'ity': 0.4}[ending]
    if ending == 'ity' and word.endswith('ctive'):
        factor = 0.1
    if word == 'active' and ending == 'ly':
        strength = 2.4
    if word == 'relative' and ending == 'ly':
        strength = 3.5
    if word == 'alternative' and ending == 'ly':
        strength = 2.1
    if word == 'exclusive' and ending == 'ly':
        strength = 1.3
    return -strength * factor


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

