"""Mark words with the English -ive / -ative family, often used for qualities or actions."""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold().strip()
    while word and not word[-1].isalpha():
        word = word[:-1]
    if word.endswith(("ively", "ative", "ive")):
        return None, -1.8
    if word.endswith(("ives", "atives")):
        return None, -0.8
    return None, 0.0

programs.sol:
"""A short-memory detector of ASCII numbers ending.

At the first non-digit after a digit run, predict a strength based on the run's
length and the new token's role: punctuation, whitespace, word, or quantity
continuation (units, month names, and number multipliers). Single digits attached
to words or following decimal points receive a boost over standalone digits.
A small positive correction lasts one more token; a new number after a space
gets a separate boost. State resets at document boundaries. Constants are training calibrations.
"""

READS = ()

MONTHS = set('january february march april may june july august september '
             'october november december jan feb mar apr jun jul aug sep sept '
             'oct nov dec'.split())
TIME = set('second seconds minute minutes hour hours day days week weeks '
           'month months year years'.split())
SCALES = set('hundred hundreds thousand thousands million millions billion '
             'billions trillion trillions'.split())
UNITS = set('mm cm km mg kg ml mcg nm ms mb gb kb hz mph kph '
            'meter meters metre metres kilometer kilometers centimetres '
            'miles mile inches inch feet foot pounds pound ounces ounce '
            'degrees degree units unit views liter liters litre litres '
            'teaspoon teaspoons tablespoon tablespoons gallon gallons pint pints '
            'GHz MHz kHz fps mbps dollar dollars cent cents euro euros '
            'rupee rupees yen yuan franc francs peso pesos'.lower().split())
SHORT_UNITS = set('m g s h min sec ft lb oz percent per'.split())
PREPOSITIONS = set('in of at by for with from as on'.split())
CONNECTORS = set('and or to'.split())
BE = set('is are was were be been being'.split())

# Responses after standalone one-digit and two-digit numbers.
LEVELS = {
    'word': (0.24, 0.85),
    'preposition': (0.34, 1.37),
    'connector': (0.13, 1.04),
    'be': (0.18, 0.87),
    'time': (-0.30, 0.22),
    'scale': (-0.39, -0.04),
    'month': (-0.17, 0.39),
    'unit': (-0.14, 0.24),
    'short_unit': (0.12, 0.75),
    'suffix': (-0.20, 0.25),
    'plural_s': (0.13, 0.72),
    'unspaced_word': (-0.22, 0.13),
    'spaces': (0.04, 1.14),
    'indent': (0.00, 0.84),
    'newline': (0.07, 0.77),
    'period': (-0.01, 0.67),
    'comma': (0.06, 0.91),
    'colon': (0.11, 0.87),
    'opening': (0.35, 1.17),
    'closing': (-0.08, 0.72),
    'compound_closing': (-0.05, 0.52),
    'line_punct': (0.03, 0.41),
    'operator': (0.05, 0.68),
    'spaced_operator': (0.15, 0.98),
    'equals': (0.23, 0.96),
    'percent': (-0.21, 0.18),
    'other': (0.14, 0.90),
}

def token_kind(s):
    """Classify the new token by its visible role at a number boundary."""
    z = s.strip()
    if not z:
        if '\n' in s or '\r' in s:
            return 'newline'
        return 'indent' if '\t' in s and ' ' in s else 'spaces'
    if z.startswith('<|'):
        return 'suffix'
    if z[0].isalpha():
        w = z.lower()
        if not s[0].isspace():
            if w == 's':
                return 'plural_s'
            if w in {'st', 'nd', 'rd', 'th'}:
                return 'suffix'
            return 'unspaced_word'
        if w in MONTHS:
            return 'month'
        if w in TIME:
            return 'time'
        if w in SCALES:
            return 'scale'
        if w in UNITS:
            return 'unit'
        if w in SHORT_UNITS:
            return 'short_unit'
        if w in PREPOSITIONS:
            return 'preposition'
        if w in CONNECTORS:
            return 'connector'
        if w in BE:
            return 'be'
        return 'word'
    if '\n' in s or '\r' in s:
        return 'line_punct'
    if z[0] in '.,:':
        return {'.': 'period', ',': 'comma', ':': 'colon'}[z[0]]
    if z[0] in '([{':
        return 'opening'
    if z[0] in ')]}':
        return 'closing' if len(z) == 1 else 'compound_closing'
    if z[0] in '%°':
        return 'percent'
    if z[0] == '=':
        return 'equals'
    if z[0] in '+-−/*×<>^–':
        return 'spaced_operator' if s[0].isspace() else 'operator'
    return 'other'

def single_digit_attachment(s):
    """How much the token to the left strengthens a one-digit completion."""
    z = s.strip()
    if not z:
        return 0.0
    if z[0].isalpha():
        return 0.46
    if z[0] == '.':
        return 0.37
    if z[0] in '+-−=/*×<>^–':
        return 0.30
    if z[0] in '([{':
        return 0.12
    if z[0] == ',':
        return 0.21
    return 0.28


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0.0, 0, '')
    _, digits, attachment, ended_digits, previous = carry
    s = prefix.token_strings[-1]
    is_digit = bool(s) and s.isascii() and s.isdecimal()
    if is_digit:
        if not digits:
            attachment = single_digit_attachment(previous)
        if digits:
            value = (0.0, -0.055, 0.060, 0.108, 0.05)[min(digits, 4)]
        elif ended_digits and previous.isspace() and '\n' not in previous:
            # A new number separated from the preceding number by a space.
            value = 0.64
        else:
            z = previous.strip()
            value = -0.07 if z and z[0] in '+-−=/*×<>^–' else 0.005
        return (doc, digits + len(s), attachment, 0, s), float(value)
    kind = token_kind(s)
    if digits:
        a, b = LEVELS[kind]
        if digits == 1:
            value = a + attachment
        else:
            value = b + 0.10 * (digits >= 3) + 0.06 * (digits >= 4)
    else:
        value = -0.004
        if kind in {'closing', 'compound_closing', 'line_punct', 'period'}:
            value = -0.025
        if ended_digits:
            value += 0.05 if ended_digits == 1 else 0.09
            if kind == 'unspaced_word':
                value *= 0.5
    return (doc, 0, 0.0, digits, s), float(value)

programs.luna:
"""Predict a sparse response around numeric expressions.

The heuristic emphasizes punctuation and token boundaries near digits rather
than the digits themselves; it resets its short history when a document ends.
"""

import unicodedata

READS = ()
AVERAGE = 0.0217


def _has_digit(text):
    return any(ch.isdigit() for ch in text)


def _separator(text):
    chars = text.strip()
    return bool(chars) and all(
        unicodedata.category(ch)[0] in "PS" for ch in chars
    )


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    near_number = any(_has_digit(part) for part in recent)

    if _separator(token) and near_number:
        value = 0.32
    elif token[:1].isspace() and near_number:
        value = 0.20
    else:
        value = AVERAGE

    return (doc, (recent + (token,))[-3:]), value

programs.sol:
"""Negative lexical pulses for driving and CJK motion/horse vocabulary.

Matches drive word forms, selected movement/animal word classes, and four
incomplete UTF-8 prefixes overlapping the CJK horse-radical block. Each
prefix leaves a pulse for the immediately following replacement-containing
token in the same document. Other tokens get a near-zero background.
This captures conspicuous negative peaks, not all smaller fluctuations;
it is not a general detector of actual driving events.
"""

READS = ()

# Token ids here identify UTF-8 prefixes, not individual words:
# E9 A6 = U+9980..99BF; A7 = 99C0..99FF; A8 = 9A00..9A3F;
# A9 = 9A40..9A7F. These overlap the horse-radical character block.
HORSE_BYTE_PREFIXES = {
    44965: (-1.9, -1.4),
    119158: (-3.7, -2.2),
    101851: (-0.73, -0.31),
    76080: (-2.9, -2.6),
}

DRIVE_WORDS = {'drive', 'drives', 'drove', 'driv', 'drv'}
DRIVER_WORDS = {'driver', 'drivers', 'driving', 'webdriver'}
# Drive, station/park, ride, steer, travel quickly.
DRIVING_GLYPHS = set('驱驅駆驻駐骑騎驾駕驶駛驰馳')
# Horse, camel, tame, steed, relay station, control a horse.
HORSE_GLYPHS = set('马馬驼駝骆駱驯馴骏駿骥驥驿驛驭馭')
FOLLOW_WORDS = {'随', '隨', '随着', '隨著'}
MAIL_WORDS = {'邮', '郵', '邮寄', '郵寄', '邮政', '郵政', '邮箱', '郵箱'}
LEAD_WORDS = {'领', '領', '领导', '領導'}
# Approach, dispatch, hurry, leave behind.
MOVEMENT_WORDS = set('临臨遣赶趕遗遺')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_tail = 0.0 if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().strip('_-./(').lower()
    tail = 0.0

    if prefix.token_ids[-1] in HORSE_BYTE_PREFIXES:
        value, tail = HORSE_BYTE_PREFIXES[prefix.token_ids[-1]]
    elif previous_tail and '\ufffd' in token:
        value = previous_tail
    elif word == 'driven':
        value = -1.32
    elif word in DRIVER_WORDS:
        value = -1.13
    elif word in DRIVE_WORDS:
        value = -0.84
    elif word in {'驾驶', '駕駛', '驱动', '驅動', '驾驭'}:
        value = -2.3
    elif len(word) == 1 and word in set('驱驅駆驻駐'):
        value = -2.8
    elif word == '骑':
        value = -2.5
    elif word == '騎':
        value = -1.8
    elif len(word) == 1 and word in DRIVING_GLYPHS:
        value = -1.8
    elif any(c in DRIVING_GLYPHS for c in word):
        value = -1.7 / max(len(word) - 0.5, 1.0)
    elif len(word) == 1 and word in HORSE_GLYPHS:
        value = -0.55
    elif word in FOLLOW_WORDS:
        value = -1.15
    elif word in MAIL_WORDS:
        value = -0.95
    elif word in LEAD_WORDS:
        value = -0.7 if len(word) == 1 else -0.35
    elif word in MOVEMENT_WORDS:
        value = -0.9
    elif word in {'旅', '乘', '辆', '輛', '散步'}:
        value = -0.55
    elif word in {'dragon', 'dragons', '龙', '龍'}:
        value = -0.4
    elif word in {'ride', 'rides', 'riding', 'rider', 'walks', 'walking', 'journey'}:
        value = -0.28
    elif word == 'stationed':
        value = -0.48
    elif word in {'distance', 'located', 'along'}:
        value = -0.15
    else:
        value = 0.003
    return (doc, tail), float(value)
